    "goal1Title": "In every city, at least 2 Hemcan staff with HEMCAN-branded vehicles purchased from Togg",
    "goal1Body": "Their job: stay in touch with the neighborhood headmen (muhtars) and villages of every district, and find people in need by following the news and social media. Then meet and follow up on their needs — one-time or monthly healthcare, rent, food cards and more — depending on their situation.",
    "goal1Orphans": "Also, to try to be there for the orphans in every city, materially and emotionally.",
