    "goal2Title": "Drug-free Neurofeedback treatment for people who want to quit addiction",
    "goal2Body": "For people addicted to alcohol and drugs — young people first — who truly want to be free of addiction, to receive Neurofeedback treatment from Dr. Tanju Sürmeli, a drug-free method we believe has a high success rate.",
    "goal2Note": "Because it is a very expensive treatment, people must genuinely want to quit. Participants will be chosen with great care.",
    "goal3Title": "In every city, a large housing complex with a shopping mall: interest-free, no down payment, very long-term homes",
    "goal3Body1": "At least 1 large housing complex with a shopping mall next to it will be built in every city. Homes will be provided on a very long-term, interest-free basis — no participation (Islamic) bank or regular bank is needed, and no down payment or participation fee of any kind is taken up front. Homes will be sold at the construction cost plus a small profit margin, interest-free and long-term, at that price. Hemcan will carry out this work itself. The home will be mortgaged; when the debt is paid off, the person takes ownership.",
    "goal3Body2": "Priority order: first, unemployed people who have no home in their family and none in their own name, and people who have a job but no home; after them, people whose family owns a home but who do not own one themselves.",
    "goal3Body3": "On the ground floor of every block, apartments will be reserved for disabled people who have no home. Unemployed people will be guaranteed well-paid jobs in the complex or the mall. No one will struggle with the payments. Married and newly married people will get easier terms depending on their number of children once they have children.",
    "goal3Note": "More details will be shared when the time comes.",
    "goalsClosing": "The remaining goals, for the welfare and good of our people and homeland, will be shared when the time comes. Our list and our road are long. May God be our friend and helper…",
