    "devicesSoonTitle": "Coming soon",
    "devicesSoonBody1": "Features like remote device control, screen sharing, or handling files/emails on your behalf don't exist in Hemcan right now — we replaced an old demo screen that promised these with this honest note instead. That kind of device control needs a real security/permission infrastructure, and is a big undertaking we'll consider separately down the line.",
    "devicesSoonBody2": "What Hemcan genuinely does right now: a real AI conversation, your daily notification routine, and remembering your chat history — all on this device. Since there's no account system yet, your settings and chat are specific to this device/browser — you'll need to set them up again on your next device.",
