    "commandTitle": "Da una instrucción",
    "commandSub": "Hemcan entiende qué hacer y te muestra sus límites.",
    "commandPlaceholder": "Por ejemplo: Prepárame para la reunión de mañana...",
    "tabAssistant": "Asistente",
