    "tabGoals": "Metas",
    "goalsPriorityNote": "Nuestras metas están ordenadas por prioridad.",
    "goal1Title": "En cada ciudad, al menos 2 empleados de Hemcan con vehículos con el logotipo de HEMCAN comprados a Togg",
    "goal1Body": "Su trabajo: mantener contacto con los muhtars (jefes de barrio) y las aldeas de cada distrito, y encontrar a personas necesitadas siguiendo las noticias y las redes sociales. Luego atender y dar seguimiento a sus necesidades —salud, alquiler, tarjetas de comida y más, de forma puntual o mensual— según su situación.",
    "goal1Orphans": "Además, procurar estar al lado de los huérfanos de cada ciudad, material y emocionalmente.",
    "goalsScope": "Prioridad: mi país, Türkiye, y después todos los países.",
    "goal2Title": "Tratamiento de Neurofeedback sin medicamentos para quienes quieren dejar una adicción",
    "goal2Body": "Para personas adictas al alcohol y a las drogas —los jóvenes primero— que de verdad quieren liberarse de la adicción: que reciban del Dr. Tanju Sürmeli el tratamiento de Neurofeedback, un método sin medicamentos que creemos que tiene una alta tasa de éxito.",
    "goal2Note": "Como es un tratamiento muy caro, las personas deben querer dejarlo de verdad. Los participantes se elegirán con mucho cuidado.",
    "goal3Title": "En cada ciudad, un gran complejo residencial con centro comercial: viviendas sin intereses, sin pago inicial y a muy largo plazo",
    "goal3Body1": "En cada ciudad se construirá al menos 1 gran complejo residencial con un centro comercial al lado. Las viviendas se darán a muy largo plazo y sin intereses: no hará falta un banco de participación ni un banco normal, y no se cobrará ningún pago inicial ni cuota de participación. Las viviendas se venderán al costo de construcción más un pequeño margen de ganancia, sin intereses y a largo plazo, a ese precio. Hemcan se encargará de esto por sí misma. La vivienda tendrá una hipoteca; cuando se termine de pagar la deuda, la persona se queda con la propiedad.",
    "goal3Body2": "Orden de prioridad: primero, personas desempleadas que no tienen vivienda en su familia ni a su nombre, y personas que tienen trabajo pero no vivienda; después, personas cuya familia tiene vivienda pero ellas no.",
    "goal3Body3": "En la planta baja de cada bloque se reservarán apartamentos para personas con discapacidad que no tengan vivienda. A las personas desempleadas se les garantizará un trabajo bien remunerado en el complejo o en el centro comercial. Nadie tendrá problemas con los pagos. Las personas casadas y recién casadas tendrán facilidades según su número de hijos cuando los tengan.",
    "goal3Note": "Más detalles se compartirán cuando llegue el momento.",
    "goalsClosing": "Las demás metas, en favor del bienestar y el bien de nuestro pueblo y nuestra patria, se compartirán cuando llegue el momento. Nuestra lista y nuestro camino son largos. Que Dios sea nuestro amigo y ayudante…",
