    "donationDisclaimer": "Nota: esta no es una aplicación de recaudación de donaciones. Cuando se alcance la meta, la donación provendrá de los ingresos propios del dueño de la app, no del dinero de los usuarios.",
    "brandMeaningTitle": "¿Qué significa \"Hemcan\"?",
    "brandMeaningBody": "Hemcan combina dos palabras turcas: \"hem\" (junto, a la par) y \"can\" (un ser querido, un amigo cercano, literalmente \"alma\"). Describe a alguien que siempre está a tu lado, como un verdadero amigo del alma: nuestro nombre lleva el espíritu de la unión, la compañía y una amistad sincera.",
