    "memorySubtitle": "El historial real de tus conversaciones con Hemcan",
    "memoryWhatBody": "Esta pantalla es el historial real de tus conversaciones en la pestaña Asistente — no es una lista inventada de \"datos aprendidos\". Está vinculada solo a la identidad de este dispositivo; puedes borrarla por completo cuando quieras desde aquí abajo.",
    "memoryHistoryTitle": "Tu historial de chat",
    "memoryClearBtn": "Borrar historial",
    "memoryEmptyBody": "Todavía no tienes ninguna conversación. Pregúntale algo a Hemcan desde la pestaña Asistente y tu historial aparecerá aquí.",
    "memoryHowTitle": "¿Cómo usa esto Hemcan?",
    "memoryHowBody": "Hemcan usa este historial para recordar tu conversación reciente mientras sigues chateando (aproximadamente los últimos 20 mensajes de ida y vuelta). Si borras los datos de tu dispositivo/navegador o pulsas \"Borrar historial\", este contexto desaparece por completo — no crea un perfil permanente ni \"inferencias inventadas\" sobre ti, solo guarda la conversación en sí.",
