    "devicesSubtitle": "La sincronización y el control real entre dispositivos todavía no forman parte de Hemcan.",
    "devicesSoonTitle": "Próximamente",
    "devicesSoonBody1": "Funciones como el control remoto de dispositivos, compartir pantalla o gestionar archivos/correos en tu nombre todavía no existen en Hemcan — reemplazamos una antigua pantalla de demostración que prometía esto por esta nota honesta. Ese tipo de control de dispositivos necesita una infraestructura real de seguridad/permisos, y es un proyecto grande que evaluaremos por separado más adelante.",
    "devicesSoonBody2": "Lo que Hemcan realmente hace ahora mismo: una conversación real con IA, tu rutina diaria de notificaciones y recordar tu historial de chat — todo en este dispositivo. Como todavía no hay un sistema de cuentas, tus ajustes y tu chat son específicos de este dispositivo/navegador — tendrás que configurarlos de nuevo en tu próximo dispositivo.",
