    "statusReady": "Tous les systèmes sont prêts",
    "encrypted": "Chiffré de bout en bout",
    "planPill": "Forfait Hemcan · Seulement {price} par mois",
    "orbReady": "Prêt",
    "orbSub": "À l'écoute · contexte à jour",
    "commandTitle": "Donne une commande",
    "commandSub": "Hemcan comprend quoi faire et te montre ses limites.",
    "commandPlaceholder": "Par exemple : Prépare-moi pour la réunion de demain...",
    "tabAssistant": "Assistant",
    "tabAutomations": "Automatisations",
    "tabMemory": "Mémoire",
    "tabDevices": "Appareils",
    "tabGoals": "Objectifs",
    "goalsPriorityNote": "Nos objectifs sont classés par ordre de priorité.",
    "goal1Title": "Dans chaque ville, au moins 2 employés de Hemcan avec des véhicules au logo HEMCAN achetés auprès de Togg",
    "goal1Body": "Leur mission : rester en contact avec les muhtars (chefs de quartier) et les villages de chaque district, et repérer les personnes dans le besoin en suivant l'actualité et les réseaux sociaux. Puis répondre à leurs besoins et en assurer le suivi — santé, loyer, cartes alimentaires et plus, ponctuellement ou chaque mois — selon leur situation.",
    "goal1Orphans": "Et aussi, s'efforcer d'être aux côtés des orphelins de chaque ville, matériellement et moralement.",
    "goalsScope": "Priorité : mon pays, la Türkiye, puis tous les pays.",
    "goal2Title": "Traitement Neurofeedback sans médicaments pour ceux qui veulent sortir de l'addiction",
    "goal2Body": "Pour les personnes dépendantes à l'alcool et aux drogues — les jeunes en priorité — qui veulent vraiment s'en libérer : leur faire suivre auprès du Dr Tanju Sürmeli le traitement Neurofeedback, une méthode sans médicaments dont nous pensons qu'elle a un taux de réussite élevé.",
    "goal2Note": "Comme il s'agit d'un traitement très coûteux, les personnes doivent vraiment vouloir arrêter. Les participants seront choisis avec grand soin.",
    "goal3Title": "Dans chaque ville, un grand ensemble résidentiel avec centre commercial : logements sans intérêts, sans apport, à très long terme",
    "goal3Body1": "Au moins 1 grand ensemble résidentiel avec un centre commercial à côté sera construit dans chaque ville. Les logements seront proposés à très long terme et sans intérêts : pas besoin de banque participative ni de banque classique, et aucun apport ni frais de participation ne sera demandé à l'avance. Les logements seront vendus au coût de construction plus une petite marge, sans intérêts et à long terme, à ce prix. Hemcan s'en chargera elle-même. Le logement sera hypothéqué ; une fois la dette remboursée, la personne en devient propriétaire.",
    "goal3Body2": "Ordre de priorité : d'abord les personnes sans emploi n'ayant pas de logement dans leur famille ni à leur nom, et celles qui ont un emploi mais pas de logement ; ensuite, celles dont la famille possède un logement mais pas elles-mêmes.",
    "goal3Body3": "Au rez-de-chaussée de chaque bâtiment, des appartements seront réservés aux personnes handicapées sans logement. Un emploi bien rémunéré sera garanti aux personnes sans emploi dans l'ensemble résidentiel ou le centre commercial. Personne n'aura de difficulté pour les paiements. Les personnes mariées et les jeunes mariés bénéficieront de facilités selon leur nombre d'enfants, une fois qu'ils en auront.",
    "goal3Note": "D'autres détails seront partagés le moment venu.",
    "goalsClosing": "Les autres objectifs, pour le bien-être et le bien de notre peuple et de notre patrie, seront partagés le moment venu. Notre liste et notre chemin sont longs. Que Dieu soit notre soutien et notre aide…",
    "planTitle": "Forfait Hemcan",
    "planHeadline": "Seulement {price} par mois",
