    "brandMeaningTitle": "Que signifie « Hemcan » ?",
    "brandMeaningBody": "Hemcan associe deux mots turcs : « hem » (ensemble, à tes côtés) et « can » (un être cher, un ami proche, littéralement « âme »). Il désigne quelqu'un qui est toujours à vos côtés, comme un véritable ami de l'âme — notre nom porte l'esprit d'unité, de solidarité et d'amitié sincère.",
