    "memoryHowTitle": "Comment Hemcan utilise-t-il ça ?",
    "memoryHowBody": "Hemcan utilise cet historique pour se souvenir de ta conversation récente pendant que tu continues à discuter (environ les 20 derniers échanges). Si tu effaces les données de ton appareil/navigateur ou que tu appuies sur \"Effacer l'historique\", ce contexte disparaît complètement — il ne crée pas de profil permanent ni de \"déductions inventées\" sur toi, il stocke juste la conversation elle-même.",
