    "devicesSoonTitle": "Bientôt disponible",
    "devicesSoonBody1": "Des fonctionnalités comme le contrôle à distance des appareils, le partage d'écran ou la gestion de fichiers/e-mails en ton nom n'existent pas encore dans Hemcan — nous avons remplacé un ancien écran de démo qui promettait tout ça par cette note honnête. Ce genre de contrôle des appareils nécessite une vraie infrastructure de sécurité/permissions, et c'est un gros chantier qu'on envisagera séparément plus tard.",
    "devicesSoonBody2": "Ce que Hemcan fait vraiment en ce moment : une vraie conversation avec l'IA, ta routine quotidienne de notifications et se souvenir de ton historique de chat — le tout sur cet appareil. Comme il n'y a pas encore de système de compte, tes réglages et ton chat sont propres à cet appareil/navigateur — tu devras les reconfigurer sur ton prochain appareil.",
