    "tabGoals": "Ziele",
    "goalsPriorityNote": "Unsere Ziele sind nach Priorität geordnet.",
    "goal1Title": "In jeder Stadt mindestens 2 Hemcan-Mitarbeitende mit Fahrzeugen mit HEMCAN-Logo, die bei Togg gekauft werden",
    "goal1Body": "Ihre Aufgabe: mit den Muhtars (Viertelvorstehern) und Dörfern jedes Bezirks in Kontakt bleiben und bedürftige Menschen über Nachrichten und soziale Medien finden. Danach ihren Bedarf decken und nachverfolgen — einmalig oder monatlich, etwa Gesundheit, Miete, Essenskarten und mehr — je nach Situation.",
    "goal1Orphans": "Außerdem: den Waisenkindern in jeder Stadt materiell und seelisch zur Seite zu stehen versuchen.",
    "goalsScope": "Priorität: mein Heimatland, die Türkei, danach alle Länder.",
    "goal2Title": "Medikamentenfreie Neurofeedback-Behandlung für Menschen, die von der Sucht loskommen wollen",
    "goal2Body": "Für alkohol- und drogenabhängige Menschen — zuerst junge Menschen —, die wirklich von der Sucht loskommen wollen: Sie sollen bei Dr. Tanju Sürmeli die Neurofeedback-Behandlung erhalten, eine medikamentenfreie Methode, von der wir glauben, dass sie eine hohe Erfolgsquote hat.",
    "goal2Note": "Da es eine sehr teure Behandlung ist, müssen die Menschen wirklich aufhören wollen. Die Teilnehmenden werden sorgfältig ausgewählt.",
    "goal3Title": "In jeder Stadt eine große Wohnanlage mit Einkaufszentrum: zinslose, sehr langfristige Wohnungen ohne Anzahlung",
    "goal3Body1": "In jeder Stadt wird mindestens 1 große Wohnanlage mit einem Einkaufszentrum nebenan gebaut. Die Wohnungen werden sehr langfristig und zinslos vergeben — weder eine Beteiligungsbank (islamische Bank) noch eine normale Bank wird benötigt, und es wird keinerlei Anzahlung oder Beteiligungsgebühr im Voraus verlangt. Die Wohnungen werden zu den Baukosten plus einem kleinen Gewinnaufschlag zinslos und langfristig zu diesem Preis verkauft. Hemcan übernimmt das selbst. Auf die Wohnung kommt eine Hypothek; ist die Schuld getilgt, geht sie ins Eigentum der Person über.",
    "goal3Body2": "Prioritätenfolge: zuerst arbeitslose Menschen, die weder in der Familie noch auf eigenen Namen eine Wohnung haben, sowie Menschen mit Arbeit, aber ohne Wohnung; danach Menschen, deren Familie eine Wohnung besitzt, sie selbst aber nicht.",
    "goal3Body3": "Im Erdgeschoss jedes Blocks werden Wohnungen für Menschen mit Behinderung ohne eigene Wohnung reserviert. Arbeitslosen wird in der Anlage oder im Einkaufszentrum ein gut bezahlter Job garantiert. Niemand soll Probleme mit den Zahlungen haben. Verheiratete und frisch verheiratete Menschen erhalten Erleichterungen je nach Kinderzahl, sobald sie Kinder haben.",
    "goal3Note": "Weitere Details werden zu gegebener Zeit mitgeteilt.",
    "goalsClosing": "Die übrigen Ziele, zum Wohl und zum Besten unseres Volkes und Heimatlandes, werden zu gegebener Zeit mitgeteilt. Unsere Liste und unser Weg sind lang. Möge Gott unser Freund und Helfer sein…",
    "planTitle": "Hemcan Plan",
    "planHeadline": "Nur {price} pro Monat",
    "planSub": "In den meisten Ländern kostet Hemcan nur 1 Einheit deiner Landeswährung. In Ländern mit hoher Inflation wie der Türkei sind es 10 Einheiten.",
