    "donationDisclaimer": "Hinweis: Dies ist keine App zum Sammeln von Spenden. Wird das Ziel erreicht, stammt die Spende aus den eigenen Einnahmen des App-Betreibers — nicht aus dem Geld der Nutzer.",
    "brandMeaningTitle": "Was bedeutet „Hemcan“?",
    "brandMeaningBody": "Hemcan verbindet zwei türkische Wörter: „hem“ (zusammen, an deiner Seite) und „can“ (ein geliebter Mensch, ein enger Freund, wörtlich „Seele“). Es beschreibt jemanden, der immer an deiner Seite ist, wie ein wahrer Seelenfreund — unser Name trägt den Geist der Einheit, des Zusammenhalts und einer herzlichen Freundschaft.",
