    "memoryKicker": "Persönlicher Kontext",
    "memoryTitle": "Gedächtnis",
    "memorySubtitle": "Der echte Chatverlauf deiner Gespräche mit Hemcan",
    "memoryWhatBody": "Dieser Bildschirm zeigt den echten Verlauf deiner Gespräche aus dem Tab „Assistent“ — keine erfundene Liste „gelernter Fakten“. Er ist nur an die Identität dieses Geräts gebunden; du kannst ihn jederzeit unten komplett löschen.",
    "memoryHistoryTitle": "Dein Chatverlauf",
    "memoryClearBtn": "Verlauf löschen",
    "memoryEmptyBody": "Du hast noch kein Gespräch. Frag Hemcan etwas im Tab „Assistent“ und dein Verlauf erscheint hier.",
    "memoryHowTitle": "Wie nutzt Hemcan das?",
    "memoryHowBody": "Hemcan nutzt diesen Verlauf, um sich an dein letztes Gespräch zu erinnern, während ihr weiter chattet (ungefähr die letzten 20 Hin-und-her-Nachrichten). Wenn du deine Geräte-/Browserdaten löschst oder auf „Verlauf löschen“ tippst, ist dieser Kontext komplett weg — es wird kein dauerhaftes Profil oder „erfundene Rückschlüsse“ über dich erstellt, es speichert einfach nur das Gespräch selbst.",
    "memoryCountLabel": "{n} Nachrichten",
    "memoryLoadFailed": "Verlauf konnte nicht geladen werden.",
    "memoryClearConfirm": "Bist du sicher, dass du deinen gesamten Chatverlauf löschen möchtest? Das kann nicht rückgängig gemacht werden.",
    "devicesKicker": "Kommandozentrale",
    "devicesTitle": "Geräte",
    "devicesSubtitle": "Echte geräteübergreifende Synchronisierung und Steuerung sind noch nicht Teil von Hemcan.",
    "devicesSoonTitle": "Demnächst",
    "devicesSoonBody1": "Funktionen wie Fernsteuerung von Geräten, Bildschirmfreigabe oder das Verwalten von Dateien/E-Mails in deinem Namen gibt es in Hemcan im Moment noch nicht — wir haben einen alten Demo-Bildschirm, der das versprach, durch diesen ehrlichen Hinweis ersetzt. Diese Art von Gerätesteuerung braucht eine echte Sicherheits-/Berechtigungsinfrastruktur und ist ein großes Vorhaben, das wir uns später separat ansehen.",
    "devicesSoonBody2": "Was Hemcan gerade wirklich kann: ein echtes KI-Gespräch, deine tägliche Benachrichtigungsroutine und das Merken deines Chatverlaufs — alles auf diesem Gerät. Da es noch kein Kontosystem gibt, sind deine Einstellungen und dein Chat an dieses Gerät/diesen Browser gebunden — auf deinem nächsten Gerät musst du sie erneut einrichten.",
