    "goalsPriorityNote": "As nossas metas estão ordenadas por prioridade.",
    "goal1Title": "Em cada cidade, pelo menos 2 funcionários da Hemcan com veículos com o logótipo HEMCAN comprados à Togg",
    "goal1Body": "A sua função: manter contacto com os muhtars (chefes de bairro) e as aldeias de cada distrito e encontrar pessoas necessitadas acompanhando as notícias e as redes sociais. Depois, atender e acompanhar as suas necessidades — saúde, renda, cartões de alimentação e mais, de forma pontual ou mensal — conforme a situação.",
    "goal1Orphans": "Além disso, procurar estar ao lado dos órfãos de cada cidade, material e emocionalmente.",
    "goalsScope": "Prioridade: o meu país, a Turquia, e depois todos os países.",
    "goal2Title": "Tratamento de Neurofeedback sem medicamentos para quem quer deixar o vício",
    "goal2Body": "Para pessoas dependentes de álcool e drogas — jovens em primeiro lugar — que realmente querem se libertar do vício: que recebam do Dr. Tanju Sürmeli o tratamento de Neurofeedback, um método sem medicamentos que acreditamos ter alta taxa de sucesso.",
    "goal2Note": "Por ser um tratamento muito caro, as pessoas precisam realmente querer parar. Os participantes serão escolhidos com muito cuidado.",
    "goal3Title": "Em cada cidade, um grande condomínio com shopping: casas sem juros, sem entrada e de prazo muito longo",
    "goal3Body1": "Em cada cidade será construído pelo menos 1 grande condomínio com um shopping ao lado. As casas serão entregues com prazo muito longo e sem juros — não será preciso banco de participação nem banco comum, e nenhuma entrada ou taxa de participação será cobrada antecipadamente. As casas serão vendidas pelo custo de construção mais uma pequena margem de lucro, sem juros e a longo prazo, a esse preço. A Hemcan cuidará disso por conta própria. A casa ficará hipotecada; quando a dívida acabar, a pessoa passa a ser a proprietária.",
    "goal3Body2": "Ordem de prioridade: primeiro, pessoas desempregadas sem casa na família nem em seu nome, e pessoas que têm emprego mas não têm casa; depois, pessoas cuja família tem casa, mas elas próprias não.",
    "goal3Body3": "No andar térreo de cada bloco serão reservados apartamentos para pessoas com deficiência que não tenham casa. Aos desempregados será garantido um emprego bem remunerado no condomínio ou no shopping. Ninguém terá dificuldade com os pagamentos. Pessoas casadas e recém-casadas terão facilidades conforme o número de filhos, quando os tiverem.",
    "goal3Note": "Mais detalhes serão compartilhados quando chegar a hora.",
    "goalsClosing": "As demais metas, para o bem-estar e o bem do nosso povo e da nossa pátria, serão compartilhadas quando chegar a hora. A nossa lista e o nosso caminho são longos. Que Deus seja o nosso amigo e ajudante…",
