    "memoryHowTitle": "Como é que o Hemcan usa isto?",
    "memoryHowBody": "O Hemcan usa este histórico para se lembrar da tua conversa recente enquanto continuas a conversar (cerca das últimas 20 trocas de mensagens). Se apagares os dados do teu dispositivo/navegador ou tocares em \"Apagar histórico\", este contexto desaparece por completo — não cria um perfil permanente nem \"inferências inventadas\" sobre ti, apenas guarda a conversa em si.",
