    "devicesSubtitle": "A sincronização e o controlo real entre dispositivos ainda não fazem parte do Hemcan.",
    "devicesSoonTitle": "Brevemente",
    "devicesSoonBody1": "Funcionalidades como o controlo remoto de dispositivos, partilha de ecrã ou a gestão de ficheiros/e-mails em teu nome ainda não existem no Hemcan — substituímos um ecrã de demonstração antigo que prometia isso por esta nota honesta. Esse tipo de controlo de dispositivos precisa de uma infraestrutura real de segurança/permissões, e é um projeto grande que vamos avaliar separadamente mais à frente.",
    "devicesSoonBody2": "O que o Hemcan faz mesmo agora: uma conversa real com IA, a tua rotina diária de notificações e lembrar-se do teu histórico de chat — tudo neste dispositivo. Como ainda não há um sistema de conta, as tuas definições e o teu chat são específicos deste dispositivo/navegador — vais ter de os configurar novamente no teu próximo dispositivo.",
