    "goalsPriorityNote": "I nostri obiettivi sono ordinati per priorità.",
    "goal1Title": "In ogni città, almeno 2 dipendenti Hemcan con veicoli con il logo HEMCAN acquistati da Togg",
    "goal1Body": "Il loro compito: restare in contatto con i muhtar (capi di quartiere) e i villaggi di ogni distretto e trovare le persone bisognose seguendo le notizie e i social media. Poi soddisfare e seguire le loro esigenze — salute, affitto, buoni pasto e altro, una tantum o mensili — in base alla situazione.",
    "goal1Orphans": "Inoltre, cercare di essere vicini agli orfani di ogni città, materialmente e moralmente.",
    "goalsScope": "Priorità: il mio paese, la Türkiye, e poi tutti i paesi.",
    "goal2Title": "Trattamento di Neurofeedback senza farmaci per chi vuole uscire dalla dipendenza",
    "goal2Body": "Per le persone dipendenti da alcol e droghe — prima i giovani — che vogliono davvero liberarsi dalla dipendenza: far seguire loro dal Dr. Tanju Sürmeli il trattamento di Neurofeedback, un metodo senza farmaci che crediamo abbia un alto tasso di successo.",
    "goal2Note": "Trattandosi di un trattamento molto costoso, le persone devono volere davvero smettere. I partecipanti saranno scelti con grande cura.",
    "goal3Title": "In ogni città, un grande complesso residenziale con centro commerciale: case senza interessi, senza anticipo e a lunghissimo termine",
    "goal3Body1": "In ogni città verrà costruito almeno 1 grande complesso residenziale con un centro commerciale accanto. Le case saranno concesse a lunghissimo termine e senza interessi: non servirà né una banca di partecipazione né una banca normale, e non verrà richiesto alcun anticipo o quota di partecipazione. Le case saranno vendute al costo di costruzione più un piccolo margine di profitto, senza interessi e a lungo termine, a quel prezzo. Hemcan farà questo lavoro da sola. Sulla casa verrà posta un'ipoteca; estinto il debito, la persona ne diventa proprietaria.",
    "goal3Body2": "Ordine di priorità: prima le persone disoccupate senza casa in famiglia né a proprio nome e le persone che hanno un lavoro ma non una casa; poi le persone la cui famiglia ha una casa ma loro no.",
    "goal3Body3": "Al piano terra di ogni blocco saranno riservati appartamenti a persone con disabilità senza casa. Ai disoccupati sarà garantito un lavoro ben retribuito nel complesso o nel centro commerciale. Nessuno avrà difficoltà con i pagamenti. Le persone sposate e quelle appena sposate avranno agevolazioni in base al numero di figli, quando ne avranno.",
    "goal3Note": "Altri dettagli saranno condivisi a tempo debito.",
    "goalsClosing": "Gli altri obiettivi, per il benessere e il bene del nostro popolo e della nostra patria, saranno condivisi a tempo debito. La nostra lista e la nostra strada sono lunghe. Che Dio sia nostro amico e nostro aiuto…",
