    "commandTitle": "Дай команду",
    "commandSub": "Hemcan понимает, что делать, и показывает свои границы.",
    "commandPlaceholder": "Например: Подготовь меня к завтрашней встрече...",
    "tabAssistant": "Ассистент",
    "tabAutomations": "Автоматизации",
    "tabMemory": "Память",
    "tabDevices": "Устройства",
    "tabGoals": "Цели",
    "goalsPriorityNote": "Наши цели расположены в порядке приоритета.",
    "goal1Title": "В каждом городе — не менее 2 сотрудников Hemcan на автомобилях с логотипом HEMCAN, приобретённых у Togg",
    "goal1Body": "Их задачи: поддерживать связь с мухтарами (старостами кварталов) и деревнями каждого района и находить нуждающихся людей, следя за новостями и соцсетями. Затем удовлетворять и отслеживать их потребности — разово или ежемесячно: здоровье, аренда, продуктовые карты и другое — в зависимости от ситуации.",
    "goal1Orphans": "Кроме того, стараться быть рядом с сиротами в каждом городе — материально и душевно.",
    "goalsScope": "Приоритет: моя страна — Турция, а затем все страны.",
    "goal2Title": "Безмедикаментозное лечение нейробиоуправлением (Neurofeedback) для тех, кто хочет избавиться от зависимости",
    "goal2Body": "Людям, зависимым от алкоголя и наркотиков, в первую очередь молодёжи, которые по-настоящему хотят избавиться от зависимости: пройти у доктора Tanju Sürmeli лечение методом Neurofeedback — без лекарств, и, как мы считаем, с высоким процентом успеха.",
    "goal2Note": "Поскольку это очень дорогое лечение, человек должен действительно хотеть бросить. Участников будут отбирать с большой тщательностью.",
    "goal3Title": "В каждом городе — большой жилой комплекс с торговым центром: жильё без процентов, без первоначального взноса, на очень длительный срок",
    "goal3Body1": "В каждом городе будет построен как минимум 1 большой жилой комплекс с торговым центром рядом. Жильё будет предоставляться на очень длительный срок и без процентов: не понадобится ни партнёрский (исламский) банк, ни обычный банк, и никакого первоначального взноса или платы за участие не потребуется. Жильё будет продаваться по себестоимости строительства с небольшой наценкой, без процентов и на длительный срок, по этой цене. Этим займётся сама Hemcan. На жильё накладывается ипотека; когда долг будет выплачен, человек станет владельцем.",
    "goal3Body2": "Порядок приоритета: сначала безработные, у которых нет жилья ни в семье, ни на своё имя, и люди с работой, но без жилья; затем те, у кого жильё есть у семьи, но нет у самих.",
    "goal3Body3": "На первом этаже каждого корпуса будут зарезервированы квартиры для людей с инвалидностью, у которых нет жилья. Безработным будет гарантирована высокооплачиваемая работа в комплексе или торговом центре. Никто не будет испытывать трудностей с платежами. Семейным и молодожёнам, когда у них появятся дети, будут предоставлены послабления в зависимости от числа детей.",
    "goal3Note": "Подробности будут опубликованы, когда придёт время.",
    "goalsClosing": "Остальные цели, направленные на благополучие и благо нашего народа и Родины, будут объявлены, когда придёт время. Наш список и наш путь длинны. Да будет Бог нам другом и помощником…",
