    "brandMeaningTitle": "Что означает «Hemcan»?",
    "brandMeaningBody": "Hemcan образовано из двух турецких слов: «hem» (вместе, рядом) и «can» (дорогой человек, близкий друг — буквально «душа»). Это тот, кто всегда рядом с тобой, как настоящая родственная душа — в нашем имени заложен дух единства, сплочённости и искренней дружбы.",
