    "memoryKicker": "Личный контекст",
    "memoryTitle": "Память",
    "memorySubtitle": "Реальная история твоих разговоров с Hemcan",
    "memoryWhatBody": "Этот экран — реальная история твоих разговоров на вкладке «Ассистент», а не выдуманный список «изученных фактов». Она привязана только к идентификатору этого устройства; ты можешь полностью удалить её в любой момент ниже.",
    "memoryHistoryTitle": "Твоя история переписки",
    "memoryClearBtn": "Очистить историю",
    "memoryEmptyBody": "У тебя пока нет ни одного разговора. Спроси о чём-нибудь Hemcan на вкладке «Ассистент», и здесь появится твоя история.",
    "memoryHowTitle": "Как Hemcan это использует?",
    "memoryHowBody": "Hemcan использует эту историю, чтобы помнить твой недавний разговор, пока вы общаетесь (примерно последние 20 сообщений туда-обратно). Если ты очистишь данные устройства/браузера или нажмёшь «Очистить историю», этот контекст исчезнет полностью — приложение не создаёт постоянный профиль и не строит «выдуманные выводы» о тебе, оно просто сохраняет сам разговор.",
    "memoryCountLabel": "{n} сообщений",
    "memoryLoadFailed": "Не удалось загрузить историю.",
    "memoryClearConfirm": "Точно хочешь удалить всю историю переписки? Это действие нельзя отменить.",
    "devicesKicker": "Командный центр",
    "devicesTitle": "Устройства",
    "devicesSubtitle": "Настоящая синхронизация и управление между устройствами пока не входят в Hemcan.",
    "devicesSoonTitle": "Скоро",
    "devicesSoonBody1": "Такие функции, как удалённое управление устройством, демонстрация экрана или работа с файлами/почтой от твоего имени, пока не существуют в Hemcan — вместо старого демо-экрана, который это обещал, мы поставили эту честную заметку. Такое управление устройствами требует настоящей инфраструктуры безопасности и разрешений — это большая задача, которую мы рассмотрим отдельно в будущем.",
    "devicesSoonBody2": "Что Hemcan действительно делает прямо сейчас: настоящий разговор с ИИ, твой ежедневный маршрут уведомлений и запоминание истории переписки — всё на этом устройстве. Поскольку системы аккаунтов пока нет, твои настройки и переписка привязаны именно к этому устройству/браузеру — на следующем устройстве их нужно будет настроить заново.",
