    "tabDevices": "الأجهزة",
    "tabGoals": "أهدافنا",
    "goalsPriorityNote": "أهدافنا مرتبة حسب الأولوية.",
    "goal1Title": "في كل مدينة، ما لا يقل عن موظفين اثنين من Hemcan بمركبات تحمل شعار HEMCAN تُشترى من Togg",
    "goal1Body": "مهامهم: التواصل مع المخاتير ومجالس القرى في كل منطقة، والعثور على المحتاجين عبر متابعة الأخبار ووسائل التواصل الاجتماعي. ثم تلبية احتياجاتهم ومتابعتها — مرة واحدة أو شهريًا، مثل الصحة والإيجار وبطاقات الطعام وغيرها — بحسب حالتهم.",
    "goal1Orphans": "وأيضًا السعي إلى الوقوف مع الأيتام في كل مدينة ماديًا ومعنويًا.",
    "goalsScope": "الأولوية: بلدي تركيا، ثم جميع الدول.",
    "goal2Title": "علاج Neurofeedback بدون أدوية لمن يريد التخلص من الإدمان",
    "goal2Body": "للأشخاص المدمنين على الكحول والمخدرات — الشباب أولًا — الذين يريدون حقًا التخلص من الإدمان: تلقي علاج Neurofeedback لدى الدكتور Tanju Sürmeli، وهو علاج بدون أدوية نعتقد أن نسبة نجاحه مرتفعة.",
    "goal2Note": "ولأنه علاج مكلف جدًا، يجب أن يكون الشخص راغبًا فعلًا في الإقلاع. وسيتم اختيار المشاركين بعناية كبيرة.",
    "goal3Title": "في كل مدينة، مجمّع سكني كبير بجوار مركز تسوق: منازل بلا فوائد وبلا دفعة مقدمة وبأقساط طويلة جدًا",
    "goal3Body1": "سيُبنى في كل مدينة مجمّع سكني كبير واحد على الأقل بجواره مركز تسوق. ستُقدَّم المنازل بأقساط طويلة جدًا وبدون فوائد، دون الحاجة إلى بنك مشاركة أو بنك عادي، ولن تُؤخذ أي دفعة مقدمة أو رسوم مشاركة مسبقًا. ستُباع المنازل بتكلفة البناء مضافًا إليها هامش ربح صغير، بدون فوائد وبأقساط طويلة الأجل، بهذا السعر. وستتولى Hemcan هذا العمل بنفسها. سيُرهَن المنزل، وعند سداد الدين تنتقل ملكيته إلى الشخص.",
    "goal3Body2": "ترتيب الأولوية: أولًا العاطلون عن العمل الذين لا يملك أحد من أسرهم منزلًا ولا يملكون منزلًا باسمهم، والأشخاص الذين لديهم عمل لكن ليس لديهم منزل؛ ثم الأشخاص الذين تملك أسرهم منزلًا ولا يملكون هم منزلًا.",
    "goal3Body3": "سيتم تخصيص الطابق الأرضي في كل مبنى لذوي الإعاقة ممن لا يملكون منزلًا. وسيُضمن للعاطلين عن العمل عمل بأجر مرتفع في المجمّع أو مركز التسوق. لن يواجه أحد صعوبة في الدفعات. وسيحصل المتزوجون والمتزوجون حديثًا على تسهيلات بحسب عدد أطفالهم عند إنجابهم.",
    "goal3Note": "سيتم مشاركة مزيد من التفاصيل عندما يحين الوقت.",
    "goalsClosing": "أما بقية الأهداف التي ستكون لخير شعبنا ووطننا ورفاهيتهما فستُعلن عندما يحين الوقت. قائمتنا وطريقنا طويلان. نسأل الله أن يكون لنا عونًا ونصيرًا…",
