    "memoryWhatBody": "هذه الشاشة هي السجل الحقيقي لمحادثاتك من تبويب المساعد — وليست قائمة وهمية بـ«معلومات تم تعلّمها». وهي مرتبطة فقط بهوية هذا الجهاز؛ يمكنك حذفها بالكامل في أي وقت من الأسفل.",
