    "devicesSoonTitle": "قريبًا",
    "devicesSoonBody1": "ميزات مثل التحكم عن بُعد بالجهاز، أو مشاركة الشاشة، أو التعامل مع الملفات/البريد الإلكتروني نيابةً عنك، غير موجودة حاليًا في Hemcan — استبدلنا شاشة تجريبية قديمة كانت تَعِد بهذا بهذه الملاحظة الصادقة بدلًا منها. هذا النوع من التحكم بالأجهزة يحتاج إلى بنية أمان وأذونات حقيقية، وهو مشروع كبير سننظر فيه بشكل منفصل لاحقًا.",
    "devicesSoonBody2": "ما يقوم به Hemcan فعليًا الآن: محادثة حقيقية مع الذكاء الاصطناعي، وروتين إشعاراتك اليومي، وتذكّر سجل محادثاتك — كل ذلك على هذا الجهاز. وبما أنه لا يوجد نظام حسابات بعد، فإن إعداداتك ومحادثاتك خاصة بهذا الجهاز/المتصفح فقط — ستحتاج إلى إعدادها من جديد على جهازك التالي.",
