    "commandPlaceholder": "उदाहरण: कल की मीटिंग के लिए मुझे तैयार करो...",
    "tabAssistant": "असिस्टेंट",
    "tabAutomations": "ऑटोमेशन",
    "tabMemory": "मेमोरी",
    "tabDevices": "डिवाइस",
    "tabGoals": "लक्ष्य",
    "goalsPriorityNote": "हमारे लक्ष्य प्राथमिकता के क्रम में रखे गए हैं।",
    "goal1Title": "हर शहर में Togg से खरीदे गए HEMCAN लोगो वाले वाहनों के साथ कम से कम 2 Hemcan कर्मचारी",
    "goal1Body": "उनका काम: हर ज़िले के मुहल्लों के मुख़्तारों (मुहतार) और गाँवों से संपर्क में रहना, और ख़बरों व सोशल मीडिया पर नज़र रखकर ज़रूरतमंद लोगों को ढूँढ़ना। फिर उनकी स्थिति के अनुसार एक बार या हर महीने स्वास्थ्य, किराया, खाने के कार्ड आदि की ज़रूरतें पूरी करना और उनका फ़ॉलो-अप करना।",
    "goal1Orphans": "साथ ही, हर शहर के अनाथ बच्चों के आर्थिक और भावनात्मक रूप से साथ खड़े रहने की कोशिश करना।",
    "goalsScope": "प्राथमिकता: मेरा अपना देश तुर्किये, उसके बाद सभी देश।",
    "goal2Title": "नशे की लत छोड़ना चाहने वालों के लिए बिना दवा Neurofeedback इलाज",
    "goal2Body": "शराब और नशे के आदी लोगों में—पहले युवाओं को—जो सच में लत से छुटकारा पाना चाहते हैं, डॉक्टर Tanju Sürmeli से बिना दवा वाला Neurofeedback इलाज दिलवाना, जिसके बारे में हमारा मानना है कि इसकी सफलता दर ऊँची है।",
    "goal2Note": "यह बहुत महँगा इलाज है, इसलिए लोगों का सच में छोड़ना चाहना ज़रूरी है। प्रतिभागियों का चयन बहुत ध्यान से किया जाएगा।",
    "goal3Title": "हर शहर में शॉपिंग मॉल के साथ एक बड़ी सोसाइटी: बिना ब्याज, बिना एडवांस, बहुत लंबी अवधि के घर",
    "goal3Body1": "हर शहर में कम से कम 1 बड़ी सोसाइटी बनेगी, जिसके पास शॉपिंग मॉल होगा। घर बहुत लंबी अवधि और बिना ब्याज के दिए जाएँगे; इसके लिए किसी भागीदारी (इस्लामी) बैंक या सामान्य बैंक की ज़रूरत नहीं होगी, और कोई डाउन पेमेंट या भागीदारी शुल्क पहले से नहीं लिया जाएगा। घर निर्माण लागत में थोड़ा-सा मुनाफ़ा जोड़कर, उसी कीमत पर बिना ब्याज और लंबी अवधि में बेचे जाएँगे। यह काम Hemcan ख़ुद करेगी। घर पर बंधक (मॉर्गेज) रहेगा; कर्ज़ चुकते ही घर व्यक्ति के नाम हो जाएगा।",
    "goal3Body2": "प्राथमिकता का क्रम: पहले वे बेरोज़गार लोग जिनके परिवार में भी घर नहीं है और जिनके अपने नाम पर भी नहीं, और वे लोग जिनके पास नौकरी है पर घर नहीं; उसके बाद वे लोग जिनके परिवार के पास घर है पर उनके अपने पास नहीं।",
    "goal3Body3": "हर ब्लॉक की सबसे निचली मंज़िल उन दिव्यांग लोगों के लिए आरक्षित रहेगी जिनके पास घर नहीं है। बेरोज़गार लोगों को सोसाइटी या मॉल में ऊँचे वेतन वाली नौकरी की गारंटी दी जाएगी। भुगतान को लेकर किसी को परेशानी नहीं होगी। शादीशुदा और नवविवाहित लोगों को बच्चे होने पर बच्चों की संख्या के अनुसार रियायतें दी जाएँगी।",
    "goal3Note": "और विवरण समय आने पर साझा किए जाएँगे।",
    "goalsClosing": "बाकी लक्ष्य, जो हमारे देशवासियों और वतन की भलाई और ख़ुशहाली के लिए होंगे, समय आने पर साझा किए जाएँगे। हमारी सूची और हमारा रास्ता लंबा है। अल्लाह हमारा साथी और मददगार हो…",
