    "memorySubtitle": "Hemcan के साथ आपकी बातचीत का असली चैट इतिहास",
    "memoryWhatBody": "यह स्क्रीन असिस्टेंट टैब में हुई आपकी असली बातचीत का इतिहास है — कोई बनावटी \"सीखी गई जानकारी\" की लिस्ट नहीं। यह सिर्फ़ इस डिवाइस की पहचान से जुड़ा है; आप इसे नीचे से कभी भी पूरी तरह मिटा सकते हैं।",
