    "memoryEmptyBody": "अभी तक आपकी कोई बातचीत नहीं है। असिस्टेंट टैब से Hemcan से कुछ पूछें, आपका इतिहास यहाँ दिखने लगेगा।",
    "memoryHowTitle": "Hemcan इसका इस्तेमाल कैसे करता है?",
    "memoryHowBody": "बातचीत जारी रखते हुए हाल की बातचीत याद रखने के लिए Hemcan इस इतिहास का इस्तेमाल करता है (लगभग पिछले 20 आगे-पीछे के मैसेज)। अगर आप अपने डिवाइस/ब्राउज़र का डेटा मिटाते हैं या \"इतिहास मिटाएँ\" पर टैप करते हैं, तो यह संदर्भ पूरी तरह ख़त्म हो जाता है — यह आपके बारे में कोई स्थायी प्रोफ़ाइल या \"बनावटी अनुमान\" नहीं बनाता, बस बातचीत को ही सहेजता है।",
