    "goal1Title": "প্রতিটি শহরে Togg থেকে কেনা HEMCAN লোগোযুক্ত গাড়ি নিয়ে কমপক্ষে ২ জন Hemcan কর্মী",
    "goal1Body": "তাদের কাজ: প্রতিটি জেলার মহল্লার মুখতার ও গ্রামগুলোর সাথে যোগাযোগ রাখা এবং খবর ও সোশ্যাল মিডিয়া অনুসরণ করে অভাবী মানুষ খুঁজে বের করা। এরপর তাদের অবস্থা অনুযায়ী এককালীন বা মাসিক স্বাস্থ্য, ভাড়া, খাবারের কার্ড ইত্যাদির প্রয়োজন মেটানো ও ফলো-আপ করা।",
    "goal1Orphans": "এছাড়া প্রতিটি শহরের এতিম ও অনাথদের আর্থিক ও মানসিকভাবে পাশে থাকার চেষ্টা করা।",
    "goalsScope": "অগ্রাধিকার: আমার নিজের দেশ তুরস্ক, তারপর সব দেশ।",
    "goal2Title": "নেশা ছাড়তে চাওয়াদের জন্য ওষুধবিহীন Neurofeedback চিকিৎসা",
    "goal2Body": "মদ ও মাদকাসক্ত মানুষদের মধ্যে—আগে তরুণদের—যারা সত্যিই নেশা থেকে মুক্তি পেতে চান, তাদের ডাক্তার Tanju Sürmeli-র কাছ থেকে ওষুধবিহীন Neurofeedback চিকিৎসা নিতে সহায়তা করা, যে পদ্ধতির সাফল্যের হার উঁচু বলে আমরা বিশ্বাস করি।",
    "goal2Note": "এটি অনেক ব্যয়বহুল চিকিৎসা, তাই মানুষের সত্যিই ছাড়তে চাওয়া জরুরি। অংশগ্রহণকারীদের অত্যন্ত যত্নের সাথে বাছাই করা হবে।",
    "goal3Title": "প্রতিটি শহরে শপিং মলসহ একটি বড় আবাসন কমপ্লেক্স: সুদহীন, অগ্রিম ছাড়া, অনেক দীর্ঘমেয়াদি বাসা",
    "goal3Body1": "প্রতিটি শহরে অন্তত ১টি বড় আবাসন কমপ্লেক্স তৈরি হবে, যার পাশে থাকবে শপিং মল। বাসা দেওয়া হবে অনেক দীর্ঘমেয়াদে ও সুদ ছাড়া; কোনো অংশগ্রহণভিত্তিক (ইসলামি) ব্যাংক বা সাধারণ ব্যাংকের প্রয়োজন হবে না, আর অগ্রিম কোনো ডাউন পেমেন্ট বা অংশগ্রহণ ফি নেওয়া হবে না। বাসাগুলো নির্মাণ খরচের ওপর সামান্য লাভ যোগ করে সেই দামেই সুদহীন ও দীর্ঘমেয়াদে বিক্রি হবে। এই কাজ Hemcan নিজেই করবে। বাসায় বন্ধক থাকবে; ঋণ শোধ হলে বাসা ব্যক্তির নামে হয়ে যাবে।",
    "goal3Body2": "অগ্রাধিকারের ক্রম: প্রথমে সেই বেকাররা যাদের পরিবারে বাসা নেই এবং নিজের নামেও নেই, আর যাদের কাজ আছে কিন্তু বাসা নেই; তারপর সেই মানুষরা যাদের পরিবারের বাসা আছে কিন্তু নিজের নেই।",
    "goal3Body3": "প্রতিটি ব্লকের নিচতলা বাসাহীন প্রতিবন্ধী মানুষদের জন্য সংরক্ষিত থাকবে। বেকারদের কমপ্লেক্সে বা মলে বেশি বেতনের চাকরির নিশ্চয়তা দেওয়া হবে। কিস্তি নিয়ে কেউ কষ্টে পড়বে না। বিবাহিত ও নবদম্পতিদের সন্তান হলে সন্তানের সংখ্যা অনুযায়ী সুবিধা দেওয়া হবে।",
    "goal3Note": "আরও বিস্তারিত সময় এলে জানানো হবে।",
    "goalsClosing": "বাকি লক্ষ্যগুলো, যা আমাদের জাতি ও দেশের কল্যাণ ও মঙ্গলের জন্য হবে, সময় এলে জানানো হবে। আমাদের তালিকা ও পথ দীর্ঘ। আল্লাহ আমাদের সহায় ও সাহায্যকারী হোন…",
