    "brandMeaningTitle": "\"Hemcan\" মানে কী?",
    "brandMeaningBody": "Hemcan দুটি তুর্কি শব্দের মিশ্রণ: \"hem\" (একসাথে, পাশে) এবং \"can\" (প্রিয়জন, ঘনিষ্ঠ বন্ধু, আক্ষরিক অর্থে \"আত্মা\")। এটি এমন একজনকে বোঝায় যে সবসময় আপনার পাশে থাকে, একজন প্রকৃত আত্মিক বন্ধুর মতো — আমাদের নামে ঐক্য, সহভাগিতা এবং আন্তরিক বন্ধুত্বের চেতনা রয়েছে।",
