    "memoryWhatBody": "এই স্ক্রিনটা অ্যাসিস্ট্যান্ট ট্যাবে হওয়া তোমার আসল কথোপকথনের ইতিহাস — কোনো বানানো \"শেখা তথ্য\"-র লিস্ট নয়। এটা শুধু এই ডিভাইসের পরিচয়ের সাথে যুক্ত; তুমি চাইলে যেকোনো সময় নিচে থেকে এটা পুরোপুরি মুছে দিতে পারো।",
