    "memoryEmptyBody": "তোমার এখনো কোনো কথোপকথন নেই। অ্যাসিস্ট্যান্ট ট্যাব থেকে Hemcan-কে কিছু জিজ্ঞেস করো, তোমার ইতিহাস এখানে দেখা যাবে।",
    "memoryHowTitle": "Hemcan এটা কীভাবে ব্যবহার করে?",
    "memoryHowBody": "কথোপকথন চালিয়ে যাওয়ার সময় তোমার সাম্প্রতিক আলাপ মনে রাখতে Hemcan এই ইতিহাস ব্যবহার করে (মোটামুটি শেষ ২০টা আদান-প্রদান করা মেসেজ)। তুমি যদি ডিভাইস/ব্রাউজারের ডেটা মুছে ফেলো বা \"ইতিহাস মুছুন\"-এ ট্যাপ করো, তাহলে এই প্রসঙ্গ পুরোপুরি হারিয়ে যায় — এটা তোমার সম্পর্কে কোনো স্থায়ী প্রোফাইল বা \"বানানো অনুমান\" তৈরি করে না, শুধু কথোপকথনটাই সংরক্ষণ করে।",
