    "devicesSoonBody1": "রিমোট ডিভাইস কন্ট্রোল, স্ক্রিন শেয়ারিং, বা তোমার হয়ে ফাইল/ইমেইল সামলানোর মতো ফিচার এখন Hemcan-এ নেই — এসবের প্রতিশ্রুতি দেওয়া পুরোনো একটা ডেমো স্ক্রিনের বদলে আমরা এই সৎ নোটটা রেখেছি। এই ধরনের ডিভাইস কন্ট্রোলের জন্য দরকার একটা আসল নিরাপত্তা/পারমিশন কাঠামো, যা একটা বড় কাজ এবং ভবিষ্যতে আলাদাভাবে বিবেচনা করা হবে।",
    "devicesSoonBody2": "Hemcan এখন সত্যিই যা করে: এই ডিভাইসে একটা আসল AI কথোপকথন, তোমার প্রতিদিনের নোটিফিকেশন রুটিন, আর তোমার চ্যাট ইতিহাস মনে রাখা। এখনো কোনো অ্যাকাউন্ট সিস্টেম না থাকায় তোমার সেটিংস আর চ্যাট শুধু এই ডিভাইস/ব্রাউজারেই সীমাবদ্ধ — পরের ডিভাইসে তোমাকে আবার সেট করতে হবে।",
    "devicesBackBtn": "অ্যাসিস্ট্যান্টে ফিরে যাও",
