    "tabGoals": "目标",
    "goalsPriorityNote": "我们的目标按优先级排序。",
    "goal1Title": "每个城市至少配备2名Hemcan员工，使用从Togg购买的带HEMCAN标志的车辆",
    "goal1Body": "他们的职责：与每个区的各社区穆赫塔尔（村社长）和村庄保持联系，通过关注新闻和社交媒体找到有需要的人；再根据他们的情况，一次性或按月满足并跟进其医疗、房租、餐卡等需求。",
    "goal1Orphans": "此外，努力在物质和精神上陪伴每座城市的孤儿。",
    "goalsScope": "优先：我的祖国土耳其，之后是所有国家。",
    "goal2Title": "为想戒除成瘾者提供无药物的 Neurofeedback（神经反馈）治疗",
    "goal2Body": "为酗酒和吸毒成瘾、真心想戒除的人——优先是年轻人——安排由 Tanju Sürmeli 医生提供的无药物 Neurofeedback 治疗，我们相信这种方法成功率很高。",
    "goal2Note": "由于这是一种非常昂贵的治疗，当事人必须真心想戒除。参与者将被慎重挑选。",
    "goal3Title": "每个城市建一个毗邻购物中心的大型社区：无利息、零首付、超长期住房",
    "goal3Body1": "每个城市至少建1个毗邻购物中心的大型社区。住房将以超长期、无利息方式提供，无需参与银行（伊斯兰银行）或普通银行，也不预先收取任何首付或参与费。住房将按建造成本加一点小利润的价格，以无利息、长期的方式出售。这项工作由 Hemcan 自己完成。住房将设置抵押，债务还清后归本人所有。",
    "goal3Body2": "优先顺序：首先是家里没有住房、本人名下也没有住房的失业者，以及有工作但没有住房的人；之后是家里有住房但本人没有的人。",
    "goal3Body3": "每栋楼的底层将留给没有住房的残障人士。失业者将获得社区或购物中心内高薪工作的保障。没有人会为还款发愁。已婚和新婚人士在有孩子后，将根据孩子数量获得更多便利。",
    "goal3Note": "更多细节将在适当的时候公布。",
    "goalsClosing": "其余造福民族与祖国的目标，将在适当的时候公布。我们的清单和道路还很长。愿真主与我们同在、助我们一臂之力……",
