    "tabDevices": "デバイス",
    "tabGoals": "目標",
    "goalsPriorityNote": "私たちの目標は優先順位の順に並んでいます。",
    "goal1Title": "すべての都市で、Togg から購入する HEMCAN ロゴ入りの車両とともに、Hemcan のスタッフを最低2人配置",
    "goal1Body": "役割：各地区のすべての地域のムフタル（地区長）や村と連絡を取り合い、ニュースやSNSをたどって支援が必要な人を見つけること。そして状況に応じて、一度きり、または毎月の医療、家賃、食事カードなどのニーズに応え、継続的にフォローすること。",
    "goal1Orphans": "また、すべての都市の孤児たちに、物質的にも精神的にも寄り添えるよう努めること。",
    "goalsScope": "優先：私の母国トルコ、その後はすべての国。",
    "goal2Title": "依存から抜け出したい人への薬を使わない Neurofeedback 治療",
    "goal2Body": "アルコールや薬物の依存症で、本気で抜け出したい人（まず若者）に、Tanju Sürmeli 医師による薬を使わない Neurofeedback 治療を受けてもらう。成功率が高いと私たちが考えている方法です。",
    "goal2Note": "非常に高額な治療のため、本人が本当にやめたいと思っていることが必要です。参加者は慎重に選ばれます。",
    "goal3Title": "すべての都市に、ショッピングモール併設の大きな住宅団地：無利子・頭金なし・超長期の住宅",
    "goal3Body1": "各都市に少なくとも1つ、ショッピングモールが隣接する大きな住宅団地を建てます。住宅は超長期・無利子で提供し、参加銀行（イスラム銀行）も通常の銀行も不要で、頭金や参加費などの前払いは一切受け取りません。住宅は建設費に少額の利益だけを上乗せした価格で、無利子・長期で販売します。この事業は Hemcan 自身が行います。住宅には抵当権を設定し、借金を完済すると本人の名義になります。",
    "goal3Body2": "優先順位：まず、家族にも自分の名義にも家がない失業中の人と、仕事はあるが家がない人。その後、家族は家を持っているが本人は持っていない人。",
    "goal3Body3": "各棟の1階は、家のない障がいのある方のために確保します。失業中の人には、団地またはモールでの高給の仕事を保証します。支払いで苦しむ人はいません。既婚者や新婚の方には、子どもができたとき、子どもの人数に応じた優遇があります。",
    "goal3Note": "詳細は時期が来たらお知らせします。",
    "goalsClosing": "残りの、国民と祖国の繁栄と善のための目標は、時が来たらお知らせします。私たちのリストと道のりは長いです。神が私たちの味方であり助け手でありますように…",
    "planTitle": "Hemcanプラン",
    "planHeadline": "月額わずか{price}",
