    "brandMeaningTitle": "「Hemcan」の意味は?",
    "brandMeaningBody": "Hemcanは、トルコ語の「hem」(一緒に、そばに)と「can」(大切な人、親しい友人。直訳すると「魂」)を組み合わせた言葉です。いつもそばにいてくれる、まるで魂の友のような存在を表しています — 私たちの名前には、団結、寄り添い、そして心からの友情の精神が込められています。",
