    "devicesSoonTitle": "近日公開",
    "devicesSoonBody1": "リモートでのデバイス操作、画面共有、あなたに代わってファイルやメールを処理する機能などは、現在Hemcanには存在しません——それらを謳っていた古いデモ画面の代わりに、この正直な説明を置きました。この種のデバイス制御には本格的なセキュリティ/権限の仕組みが必要で、大掛かりな取り組みになるため、今後あらためて検討する予定です。",
    "devicesSoonBody2": "Hemcanが今できることは：このデバイス上での本物のAI会話、毎日の通知ルーティン、そしてチャット履歴を覚えておくことです。まだアカウントの仕組みがないため、設定やチャットはこのデバイス/ブラウザに限定されます——次のデバイスでは、もう一度設定し直す必要があります。",
