    "tabGoals": "목표",
    "goalsPriorityNote": "우리의 목표는 우선순위 순서로 나열되어 있어요.",
    "goal1Title": "모든 도시에서 Togg에서 구입한 HEMCAN 로고 차량과 함께 Hemcan 직원 최소 2명",
    "goal1Body": "역할: 각 지역의 모든 동네 무흐타르(이장)와 마을과 연락을 유지하고, 뉴스와 소셜 미디어를 살피며 도움이 필요한 사람을 찾는 것. 그리고 상황에 따라 일회성 또는 매달 의료, 월세, 식사 카드 등의 필요를 채우고 꾸준히 살피는 것.",
    "goal1Orphans": "또한 모든 도시의 고아들 곁에서 물질적으로나 정신적으로 함께하려고 노력하는 것.",
    "goalsScope": "우선순위: 제 조국 튀르키예, 그다음 모든 나라.",
    "goal2Title": "중독에서 벗어나고 싶은 분께 약 없는 Neurofeedback 치료",
    "goal2Body": "알코올과 약물 중독으로 정말 벗어나고 싶은 사람들—청년 우선—이 Tanju Sürmeli 박사에게 약 없는 Neurofeedback 치료를 받을 수 있도록 하는 것. 성공률이 높다고 저희가 믿는 방법이에요.",
    "goal2Note": "매우 비싼 치료이기 때문에 본인이 정말 끊고 싶어 해야 해요. 참여자는 신중하게 선발됩니다.",
    "goal3Title": "모든 도시에 쇼핑몰이 딸린 대규모 단지: 무이자, 선납금 없는 초장기 주택",
    "goal3Body1": "각 도시에 적어도 1곳, 쇼핑몰이 붙어 있는 대규모 단지를 짓습니다. 집은 초장기·무이자로 제공되며, 참여은행(이슬람 은행)이나 일반 은행이 필요 없고, 계약금이나 참여금 같은 선납금은 일절 받지 않습니다. 집은 건축 원가에 작은 이익만 더한 가격 그대로, 무이자·장기로 판매합니다. 이 일은 Hemcan이 직접 합니다. 집에는 저당이 설정되고, 빚을 다 갚으면 본인 명의가 됩니다.",
    "goal3Body2": "우선순위: 먼저 가족에게도 본인 명의로도 집이 없는 실직자와, 직장은 있지만 집이 없는 사람. 그다음으로 가족은 집이 있지만 본인은 없는 사람.",
    "goal3Body3": "각 동의 1층은 집이 없는 장애인을 위해 따로 남겨 둡니다. 실직자에게는 단지나 쇼핑몰에서 높은 급여의 일자리를 보장합니다. 납부 때문에 힘들어하는 사람은 없을 거예요. 기혼자와 신혼부부에게는 아이가 생기면 자녀 수에 따라 혜택을 드립니다.",
    "goal3Note": "더 자세한 내용은 때가 되면 공유할게요.",
    "goalsClosing": "나머지 국민과 조국의 복지와 선을 위한 목표들은 때가 되면 공유할게요. 우리의 목록과 길은 깁니다. 신께서 우리의 벗이자 도움이 되어 주시길…",
