    "goalsScope": "Prioritas: negara saya, Türkiye, lalu semua negara.",
    "goal2Title": "Terapi Neurofeedback tanpa obat bagi yang ingin lepas dari kecanduan",
    "goal2Body": "Bagi pecandu alkohol dan narkoba — anak muda diutamakan — yang sungguh-sungguh ingin lepas dari kecanduan: mendapatkan terapi Neurofeedback dari dr. Tanju Sürmeli, metode tanpa obat yang kami yakini memiliki tingkat keberhasilan tinggi.",
    "goal2Note": "Karena biayanya sangat mahal, orang tersebut harus benar-benar ingin berhenti. Peserta akan dipilih dengan sangat hati-hati.",
    "goal3Title": "Di setiap kota, kompleks hunian besar dengan pusat perbelanjaan: rumah tanpa bunga, tanpa uang muka, tenor sangat panjang",
    "goal3Body1": "Di setiap kota akan dibangun minimal 1 kompleks hunian besar dengan pusat perbelanjaan di sebelahnya. Rumah diberikan dengan tenor sangat panjang dan tanpa bunga — tidak perlu bank partisipasi (syariah) maupun bank biasa, dan tidak ada uang muka atau biaya partisipasi apa pun di awal. Rumah dijual sesuai biaya pembangunan ditambah keuntungan kecil, tanpa bunga dan berjangka panjang, dengan harga itu. Hemcan sendiri yang akan mengerjakannya. Rumah akan dijaminkan (hipotek); setelah utang lunas, rumah menjadi milik orang tersebut.",
    "goal3Body2": "Urutan prioritas: pertama, penganggur yang keluarganya tidak punya rumah dan dirinya sendiri juga tidak, serta orang yang punya pekerjaan tetapi belum punya rumah; setelah itu, orang yang keluarganya punya rumah tetapi dirinya tidak.",
    "goal3Body3": "Lantai dasar setiap blok akan dikhususkan bagi penyandang disabilitas yang belum punya rumah. Para penganggur akan dijamin pekerjaan bergaji tinggi di kompleks atau pusat perbelanjaan. Tidak ada yang akan kesulitan soal pembayaran. Pasangan menikah dan pengantin baru akan mendapat kemudahan sesuai jumlah anak setelah mereka punya anak.",
    "goal3Note": "Detail lebih lanjut akan dibagikan pada waktunya.",
    "goalsClosing": "Target-target lainnya, demi kesejahteraan dan kebaikan bangsa dan tanah air, akan dibagikan pada waktunya. Daftar dan jalan kami masih panjang. Semoga Allah menjadi penolong dan pelindung kami…",
