    "brandMeaningTitle": "Apa arti \"Hemcan\"?",
    "brandMeaningBody": "Hemcan menggabungkan dua kata Turki: \"hem\" (bersama, di sisimu) dan \"can\" (orang tersayang, sahabat dekat, secara harfiah berarti \"jiwa\"). Ini menggambarkan seseorang yang selalu ada di sisimu, seperti sahabat jiwa sejati — nama kami membawa semangat persatuan, kebersamaan, dan persahabatan yang tulus.",
