    "memoryHowTitle": "Bagaimana Hemcan menggunakan ini?",
    "memoryHowBody": "Hemcan menggunakan riwayat ini untuk mengingat percakapan terbarumu selagi kamu terus mengobrol (kira-kira 20 pesan bolak-balik terakhir). Jika kamu menghapus data perangkat/browser atau menekan \"Hapus riwayat\", konteks ini akan hilang sepenuhnya — ini tidak membangun profil permanen atau \"kesimpulan karangan\" tentang dirimu, ini hanya menyimpan percakapannya sendiri.",
