    "devicesSubtitle": "Sinkronisasi dan kontrol lintas perangkat yang sesungguhnya belum jadi bagian dari Hemcan.",
    "devicesSoonTitle": "Segera hadir",
    "devicesSoonBody1": "Fitur seperti kontrol perangkat jarak jauh, berbagi layar, atau menangani file/email atas namamu belum ada di Hemcan sekarang — kami mengganti layar demo lama yang menjanjikan ini dengan catatan jujur ini. Kontrol perangkat semacam itu butuh infrastruktur keamanan/izin yang sungguhan, dan ini pekerjaan besar yang akan kami pertimbangkan terpisah di kemudian hari.",
    "devicesSoonBody2": "Yang benar-benar dilakukan Hemcan sekarang: percakapan AI yang sungguhan, rutinitas notifikasi harianmu, dan mengingat riwayat obrolanmu — semuanya di perangkat ini. Karena belum ada sistem akun, pengaturan dan obrolanmu khusus untuk perangkat/browser ini — kamu perlu mengaturnya lagi di perangkat berikutnya.",
