    "statusReady": "Mọi hệ thống đã sẵn sàng",
    "encrypted": "Mã hóa đầu cuối",
    "planPill": "Gói Hemcan · Chỉ {price} mỗi tháng",
    "orbReady": "Sẵn sàng",
    "orbSub": "Đang lắng nghe · ngữ cảnh cập nhật",
    "commandTitle": "Đưa ra lệnh",
    "commandSub": "Hemcan hiểu phải làm gì và cho bạn thấy giới hạn của nó.",
    "commandPlaceholder": "Ví dụ: Chuẩn bị cho tôi cuộc họp ngày mai...",
    "tabAssistant": "Trợ lý",
    "tabAutomations": "Tự động hóa",
    "tabMemory": "Bộ nhớ",
    "tabDevices": "Thiết bị",
    "tabGoals": "Mục tiêu",
    "goalsPriorityNote": "Các mục tiêu của chúng tôi được sắp xếp theo thứ tự ưu tiên.",
    "goal1Title": "Ở mỗi thành phố, ít nhất 2 nhân viên Hemcan với xe mang logo HEMCAN mua từ Togg",
    "goal1Body": "Nhiệm vụ: giữ liên lạc với các muhtar (trưởng khu phố) và làng xã ở mọi quận, tìm những người cần giúp đỡ qua tin tức và mạng xã hội. Sau đó đáp ứng và theo dõi nhu cầu của họ — một lần hoặc hằng tháng, như y tế, tiền thuê nhà, thẻ ăn uống và hơn thế nữa — tùy hoàn cảnh.",
    "goal1Orphans": "Ngoài ra, cố gắng đồng hành cùng trẻ mồ côi ở mỗi thành phố cả về vật chất lẫn tinh thần.",
    "goalsScope": "Ưu tiên: đất nước của tôi, Thổ Nhĩ Kỳ, sau đó là tất cả các nước.",
    "goal2Title": "Điều trị Neurofeedback không dùng thuốc cho người muốn cai nghiện",
    "goal2Body": "Dành cho những người nghiện rượu và ma túy — ưu tiên người trẻ — thật sự muốn thoát khỏi nghiện: được bác sĩ Tanju Sürmeli điều trị bằng Neurofeedback, phương pháp không dùng thuốc mà chúng tôi tin có tỷ lệ thành công cao.",
    "goal2Note": "Vì đây là phương pháp rất tốn kém nên người tham gia phải thật sự muốn bỏ. Người tham gia sẽ được chọn lọc rất cẩn thận.",
    "goal3Title": "Mỗi thành phố một khu dân cư lớn kèm trung tâm thương mại: nhà không lãi suất, không trả trước, kỳ hạn rất dài",
    "goal3Body1": "Mỗi thành phố sẽ xây ít nhất 1 khu dân cư lớn có trung tâm thương mại bên cạnh. Nhà được cung cấp với kỳ hạn rất dài và không lãi suất — không cần ngân hàng tham gia (Hồi giáo) hay ngân hàng thông thường, và không thu bất kỳ khoản trả trước hay phí tham gia nào. Nhà sẽ được bán đúng giá thành xây dựng cộng một khoản lợi nhuận nhỏ, không lãi suất và dài hạn, theo mức giá đó. Hemcan sẽ tự mình thực hiện. Nhà sẽ được thế chấp; khi trả hết nợ, người mua sẽ đứng tên sở hữu.",
    "goal3Body2": "Thứ tự ưu tiên: trước hết là người thất nghiệp mà gia đình không có nhà và bản thân cũng không có nhà, cùng người có việc làm nhưng chưa có nhà; sau đó là người mà gia đình có nhà nhưng bản thân không có.",
    "goal3Body3": "Tầng trệt của mỗi block sẽ dành cho người khuyết tật chưa có nhà. Người thất nghiệp sẽ được đảm bảo việc làm lương cao trong khu dân cư hoặc trung tâm thương mại. Sẽ không ai gặp khó khăn về thanh toán. Người đã kết hôn và vợ chồng mới cưới sẽ được ưu đãi theo số con khi họ có con.",
    "goal3Note": "Chi tiết hơn sẽ được chia sẻ khi đến lúc.",
    "goalsClosing": "Các mục tiêu còn lại, vì phúc lợi và điều tốt đẹp của dân tộc và đất nước, sẽ được chia sẻ khi đến lúc. Danh sách và con đường của chúng tôi còn dài. Mong Thượng đế là người bạn và là chỗ dựa của chúng tôi…",
    "planTitle": "Gói Hemcan",
    "planHeadline": "Chỉ {price} mỗi tháng",
    "planSub": "Ở hầu hết các quốc gia, Hemcan chỉ có giá 1 đơn vị tiền tệ địa phương của bạn. Ở các quốc gia có lạm phát cao như Thổ Nhĩ Kỳ, giá là 10 đơn vị.",
    "planCurrencyLabel": "Chọn đơn vị tiền tệ",
    "planCurrencyAuto": "Chúng tôi đã tự động nhận diện tiền tệ địa phương của bạn — bạn có thể thay đổi nếu muốn.",
    "planFeaturesTitle": "Bao gồm những gì",
