    "devicesSoonTitle": "Sắp ra mắt",
    "devicesSoonBody1": "Các tính năng như điều khiển thiết bị từ xa, chia sẻ màn hình, hay xử lý tệp/email thay bạn hiện chưa có trong Hemcan — chúng tôi đã thay màn hình demo cũ từng hứa hẹn những điều này bằng ghi chú trung thực này. Loại điều khiển thiết bị đó cần một hạ tầng bảo mật/quyền truy cập thật sự, và là một việc lớn chúng tôi sẽ cân nhắc riêng sau này.",
    "devicesSoonBody2": "Những gì Hemcan thực sự làm ngay bây giờ: một cuộc trò chuyện AI thật, thói quen thông báo hằng ngày của bạn, và nhớ lịch sử trò chuyện của bạn — tất cả trên thiết bị này. Vì chưa có hệ thống tài khoản, cài đặt và cuộc trò chuyện của bạn chỉ dành riêng cho thiết bị/trình duyệt này — bạn sẽ cần thiết lập lại trên thiết bị tiếp theo.",
