    "goal1Title": "ในทุกเมืองมีพนักงาน Hemcan อย่างน้อย 2 คน พร้อมรถที่มีโลโก้ HEMCAN ซึ่งซื้อจาก Togg",
    "goal1Body": "หน้าที่ของพวกเขา: ติดต่อกับมุฟตาร์ (ผู้ใหญ่บ้าน/หัวหน้าชุมชน) และหมู่บ้านของทุกอำเภอ และค้นหาผู้ที่ต้องการความช่วยเหลือผ่านข่าวและโซเชียลมีเดีย จากนั้นตอบสนองและติดตามความต้องการของพวกเขา ทั้งแบบครั้งเดียวหรือรายเดือน เช่น สุขภาพ ค่าเช่า บัตรอาหาร และอื่น ๆ ตามสถานการณ์",
    "goal1Orphans": "นอกจากนี้ พยายามอยู่เคียงข้างเด็กกำพร้าในทุกเมืองทั้งด้านวัตถุและจิตใจ",
    "goalsScope": "ลำดับความสำคัญ: ประเทศของฉันคือตุรกี จากนั้นจึงทุกประเทศ",
    "goal2Title": "การรักษา Neurofeedback แบบไม่ใช้ยา สำหรับผู้ที่อยากเลิกการติด",
    "goal2Body": "สำหรับผู้ติดแอลกอฮอล์และยาเสพติด โดยเน้นเยาวชนก่อน ที่ต้องการเลิกจริง ๆ: ให้ได้รับการรักษาด้วย Neurofeedback จากแพทย์ Tanju Sürmeli ซึ่งเป็นวิธีที่ไม่ใช้ยาและเราเชื่อว่ามีอัตราความสำเร็จสูง",
    "goal2Note": "เนื่องจากเป็นการรักษาที่ราคาสูงมาก ผู้เข้าร่วมจึงต้องตั้งใจเลิกจริง ๆ และจะมีการคัดเลือกอย่างพิถีพิถัน",
    "goal3Title": "ทุกเมืองมีโครงการที่อยู่อาศัยขนาดใหญ่ติดห้างสรรพสินค้า: บ้านไม่มีดอกเบี้ย ไม่ต้องจ่ายล่วงหน้า ผ่อนระยะยาวมาก",
    "goal3Body1": "ทุกเมืองจะสร้างโครงการที่อยู่อาศัยขนาดใหญ่อย่างน้อย 1 แห่ง โดยมีห้างสรรพสินค้าอยู่ติดกัน บ้านจะให้ผ่อนระยะยาวมากและไม่มีดอกเบี้ย ไม่ต้องใช้ธนาคารแบบมีส่วนร่วม (อิสลาม) หรือธนาคารทั่วไป และจะไม่เก็บเงินดาวน์หรือค่าเข้าร่วมใด ๆ ล่วงหน้า บ้านจะขายในราคาต้นทุนการก่อสร้างบวกกำไรเล็กน้อย แบบไม่มีดอกเบี้ยและผ่อนระยะยาว ตามราคานั้น Hemcan จะดำเนินการเอง บ้านจะมีการจำนอง เมื่อชำระหนี้หมดแล้วบ้านจะเป็นของผู้ซื้อ",
    "goal3Body2": "ลำดับความสำคัญ: อันดับแรกคือผู้ว่างงานที่ครอบครัวไม่มีบ้านและตนเองก็ไม่มีบ้าน รวมถึงผู้ที่มีงานทำแต่ยังไม่มีบ้าน จากนั้นคือผู้ที่ครอบครัวมีบ้านแต่ตนเองไม่มี",
    "goal3Body3": "ชั้นล่างสุดของทุกอาคารจะสงวนไว้ให้ผู้พิการที่ไม่มีบ้าน ผู้ว่างงานจะได้รับการรับประกันงานเงินเดือนสูงในโครงการหรือห้างสรรพสินค้า จะไม่มีใครลำบากเรื่องการชำระเงิน คู่สมรสและผู้เพิ่งแต่งงานจะได้รับความสะดวกตามจำนวนบุตรเมื่อมีบุตร",
    "goal3Note": "รายละเอียดเพิ่มเติมจะแจ้งให้ทราบเมื่อถึงเวลา",
    "goalsClosing": "เป้าหมายที่เหลือเพื่อความผาสุกและประโยชน์ของประชาชนและมาตุภูมิ จะแจ้งให้ทราบเมื่อถึงเวลา รายการและเส้นทางของเรายังยาวไกล ขอพระเจ้าทรงเป็นเพื่อนและผู้ช่วยเหลือเรา…",
