    "memoryHowTitle": "Hemcan ใช้สิ่งนี้ยังไง?",
    "memoryHowBody": "Hemcan ใช้ประวัตินี้เพื่อจดจำบทสนทนาล่าสุดของคุณระหว่างที่คุณคุยต่อไป (ประมาณ 20 ข้อความล่าสุดที่โต้ตอบกัน) ถ้าคุณล้างข้อมูลอุปกรณ์/เบราว์เซอร์ หรือกด \"ล้างประวัติ\" บริบทนี้จะหายไปทั้งหมด — มันไม่ได้สร้างโปรไฟล์ถาวรหรือ \"ข้อสรุปที่แต่งขึ้น\" เกี่ยวกับคุณ มันแค่เก็บบทสนทนาไว้เท่านั้น",
