    "devicesSoonBody1": "ฟีเจอร์อย่างการควบคุมอุปกรณ์จากระยะไกล การแชร์หน้าจอ หรือการจัดการไฟล์/อีเมลแทนคุณ ยังไม่มีอยู่ใน Hemcan ตอนนี้ — เราแทนที่หน้าจอเดโมเก่าที่เคยสัญญาไว้เรื่องนี้ด้วยข้อความที่ตรงไปตรงมานี้แทน การควบคุมอุปกรณ์แบบนั้นต้องการโครงสร้างพื้นฐานด้านความปลอดภัย/สิทธิ์การเข้าถึงที่แท้จริง และเป็นงานใหญ่ที่เราจะพิจารณาแยกต่างหากในอนาคต",
    "devicesSoonBody2": "สิ่งที่ Hemcan ทำได้จริง ๆ ตอนนี้: บทสนทนา AI ที่แท้จริง กิจวัตรการแจ้งเตือนประจำวันของคุณ และการจดจำประวัติแชทของคุณ — ทั้งหมดบนอุปกรณ์นี้ เนื่องจากยังไม่มีระบบบัญชี การตั้งค่าและแชทของคุณจึงเจาะจงกับอุปกรณ์/เบราว์เซอร์นี้เท่านั้น — คุณจะต้องตั้งค่าใหม่อีกครั้งบนอุปกรณ์เครื่องถัดไป",
