    "goal1Title": "ہر شہر میں Togg سے خریدی گئی HEMCAN لوگو والی گاڑیوں کے ساتھ کم از کم 2 Hemcan ملازمین",
    "goal1Body": "ان کا کام: ہر ضلع کے ہر محلے کے مختاروں (مُختار) اور دیہات سے رابطے میں رہنا، اور خبروں اور سوشل میڈیا پر نظر رکھ کر ضرورت مند لوگوں کو تلاش کرنا۔ پھر ان کی حالت کے مطابق ایک بار یا ماہانہ صحت، کرایہ، کھانے کے کارڈ وغیرہ کی ضروریات پوری کرنا اور ان کا فالو اپ کرنا۔",
    "goal1Orphans": "اس کے علاوہ ہر شہر کے یتیم بچوں کے مالی اور جذباتی طور پر ساتھ کھڑے ہونے کی کوشش کرنا۔",
    "goalsScope": "ترجیح: میرا اپنا ملک ترکیہ، اس کے بعد تمام ممالک۔",
    "goal2Title": "نشے سے چھٹکارا چاہنے والوں کے لیے بغیر دوا Neurofeedback علاج",
    "goal2Body": "شراب اور منشیات کے عادی لوگوں کے لیے — پہلے نوجوان — جو واقعی لت سے نجات چاہتے ہیں: ڈاکٹر Tanju Sürmeli سے بغیر دوا Neurofeedback علاج کروانا، جس کے بارے میں ہمارا یقین ہے کہ اس کی کامیابی کی شرح بلند ہے۔",
    "goal2Note": "چونکہ یہ بہت مہنگا علاج ہے، اس لیے لوگوں کا واقعی چھوڑنا چاہنا ضروری ہے۔ شرکاء کا انتخاب بہت احتیاط سے کیا جائے گا۔",
    "goal3Title": "ہر شہر میں شاپنگ مال کے ساتھ ایک بڑی سوسائٹی: بغیر سود، بغیر پیشگی ادائیگی، بہت طویل مدت کے مکان",
    "goal3Body1": "ہر شہر میں کم از کم 1 بڑی سوسائٹی بنے گی جس کے ساتھ شاپنگ مال ہوگا۔ مکان بہت طویل مدت اور بغیر سود کے دیے جائیں گے؛ کسی شراکتی (اسلامی) بینک یا عام بینک کی ضرورت نہیں ہوگی، اور کوئی ڈاؤن پیمنٹ یا شراکتی فیس پیشگی نہیں لی جائے گی۔ مکان تعمیراتی لاگت پر معمولی سا منافع جوڑ کر اسی قیمت پر بغیر سود اور طویل مدت میں فروخت کیے جائیں گے۔ یہ کام Hemcan خود کرے گی۔ مکان رہن رکھا جائے گا؛ قرض ختم ہونے پر مکان شخص کے نام ہو جائے گا۔",
    "goal3Body2": "ترجیح کی ترتیب: پہلے وہ بے روزگار لوگ جن کے خاندان میں بھی مکان نہیں اور اپنے نام پر بھی نہیں، اور وہ لوگ جن کے پاس نوکری ہے مگر مکان نہیں؛ اس کے بعد وہ لوگ جن کے خاندان کے پاس مکان ہے مگر ان کے اپنے پاس نہیں۔",
    "goal3Body3": "ہر بلاک کی سب سے نچلی منزل ان معذور افراد کے لیے مختص ہوگی جن کے پاس مکان نہیں۔ بے روزگار لوگوں کو سوسائٹی یا مال میں اونچی تنخواہ والی نوکری کی ضمانت دی جائے گی۔ ادائیگیوں کے معاملے میں کسی کو پریشانی نہیں ہوگی۔ شادی شدہ اور نئے شادی شدہ افراد کو بچے ہونے پر بچوں کی تعداد کے مطابق سہولتیں دی جائیں گی۔",
