    "brandMeaningTitle": "\"Hemcan\" کا کیا مطلب ہے؟",
    "brandMeaningBody": "Hemcan دو ترکی الفاظ کا مجموعہ ہے: \"hem\" (ساتھ، پہلو میں) اور \"can\" (عزیز شخص، قریبی دوست، لفظی معنی \"روح\")۔ یہ اُس شخص کی عکاسی کرتا ہے جو ہمیشہ آپ کے ساتھ رہتا ہے، ایک سچے روحانی دوست کی طرح — ہمارے نام میں اتحاد، ساتھ اور مخلص دوستی کی روح شامل ہے۔",
