    "memorySubtitle": "Hemcan کے ساتھ تمہاری گفتگو کی اصل چیٹ ہسٹری",
    "memoryWhatBody": "یہ اسکرین اسسٹنٹ ٹیب میں تمہاری اصل گفتگو کی تاریخ دکھاتی ہے — یہ کوئی من گھڑت \"سیکھی گئی معلومات\" کی فہرست نہیں۔ یہ صرف اسی ڈیوائس کی شناخت سے جڑی ہوئی ہے؛ تم اسے نیچے سے کسی بھی وقت مکمل طور پر مٹا سکتے ہو۔",
    "memoryHistoryTitle": "تمہاری چیٹ ہسٹری",
    "memoryClearBtn": "ہسٹری صاف کرو",
    "memoryEmptyBody": "ابھی تمہاری کوئی گفتگو نہیں ہے۔ اسسٹنٹ ٹیب سے Hemcan سے کچھ پوچھو اور تمہاری ہسٹری یہاں نظر آئے گی۔",
    "memoryHowTitle": "Hemcan اسے کیسے استعمال کرتا ہے؟",
    "memoryHowBody": "Hemcan اس ہسٹری کو استعمال کرتا ہے تاکہ گفتگو جاری رکھتے ہوئے تمہاری حالیہ باتیں یاد رکھ سکے (تقریباً پچھلے 20 آگے پیچھے پیغامات)۔ اگر تم اپنے ڈیوائس/براؤزر کا ڈیٹا صاف کرو یا \"ہسٹری صاف کرو\" پر ٹیپ کرو، تو یہ سیاق و سباق مکمل طور پر ختم ہو جاتا ہے — یہ تمہارا کوئی مستقل پروفائل یا تمہارے بارے میں \"من گھڑت اندازے\" نہیں بناتا، بس گفتگو خود محفوظ رکھتا ہے۔",
    "memoryCountLabel": "{n} پیغامات",
    "memoryLoadFailed": "ہسٹری لوڈ نہیں ہو سکی۔",
    "memoryClearConfirm": "کیا تمہیں یقین ہے کہ تم اپنی پوری چیٹ ہسٹری حذف کرنا چاہتے ہو؟ یہ عمل واپس نہیں ہو سکتا۔",
    "devicesKicker": "کمانڈ سینٹر",
    "devicesTitle": "ڈیوائسز",
    "devicesSubtitle": "ڈیوائسز کے درمیان اصل سنکرونائزیشن اور کنٹرول ابھی تک Hemcan کا حصہ نہیں ہے۔",
    "devicesSoonTitle": "جلد آ رہا ہے",
    "devicesSoonBody1": "ریموٹ ڈیوائس کنٹرول، اسکرین شیئرنگ، یا تمہاری جانب سے فائلز/ای میلز سنبھالنے جیسی خصوصیات ابھی Hemcan میں موجود نہیں ہیں — ہم نے ایک پرانی ڈیمو اسکرین جو یہ وعدہ کرتی تھی، اس کی جگہ یہ ایماندارانہ نوٹ رکھ دیا ہے۔ اس قسم کے ڈیوائس کنٹرول کے لیے ایک حقیقی سیکیورٹی/اجازت کے ڈھانچے کی ضرورت ہے، اور یہ ایک بڑا کام ہے جس پر ہم آگے چل کر الگ سے غور کریں گے۔",
    "devicesSoonBody2": "Hemcan اس وقت واقعی جو کچھ کرتا ہے: ایک حقیقی AI گفتگو، تمہاری روزانہ کی نوٹیفیکیشن روٹین، اور تمہاری چیٹ ہسٹری یاد رکھنا — یہ سب اسی ڈیوائس پر۔ چونکہ ابھی کوئی اکاؤنٹ سسٹم نہیں ہے، اس لیے تمہاری سیٹنگز اور چیٹ صرف اسی ڈیوائس/براؤزر تک محدود ہیں — تمہیں اپنے اگلے ڈیوائس پر انہیں دوبارہ سیٹ اپ کرنا ہوگا۔",
