    "goalsPriorityNote": "Malengo yetu yamepangwa kwa mpangilio wa kipaumbele.",
    "goal1Title": "Katika kila jiji, wafanyakazi wasiopungua 2 wa Hemcan wenye magari yenye nembo ya HEMCAN yatakayonunuliwa kutoka Togg",
    "goal1Body": "Kazi yao: kuwasiliana na muhtar (wakuu wa mitaa) na vijiji vya kila wilaya, na kuwapata watu wenye uhitaji kwa kufuatilia habari na mitandao ya kijamii. Kisha kutimiza na kufuatilia mahitaji yao — mara moja au kila mwezi, kama afya, kodi, kadi za chakula na mengineyo — kulingana na hali yao.",
    "goal1Orphans": "Pia, kujitahidi kuwa karibu na yatima katika kila jiji, kimali na kihisia.",
    "goalsScope": "Kipaumbele: nchi yangu, Türkiye, na baadaye nchi zote.",
    "goal2Title": "Matibabu ya Neurofeedback bila dawa kwa wanaotaka kuacha uraibu",
    "goal2Body": "Kwa watu waraibu wa pombe na dawa za kulevya — vijana kwanza — wanaotaka kweli kuachana na uraibu: kupata matibabu ya Neurofeedback kutoka kwa Dkt. Tanju Sürmeli, njia isiyotumia dawa ambayo tunaamini ina kiwango cha juu cha mafanikio.",
    "goal2Note": "Kwa kuwa ni matibabu ghali sana, watu lazima wawe wanataka kuacha kweli. Washiriki watachaguliwa kwa uangalifu mkubwa.",
    "goal3Title": "Katika kila jiji, makazi makubwa yenye jengo la maduka: nyumba bila riba, bila malipo ya awali, kwa muda mrefu sana",
    "goal3Body1": "Katika kila jiji kutajengwa angalau makazi 1 makubwa yenye jengo la maduka jirani. Nyumba zitatolewa kwa muda mrefu sana na bila riba — hakuna haja ya benki ya ushirika (ya Kiislamu) wala benki ya kawaida, na hakuna malipo ya awali au ada ya ushiriki itakayochukuliwa mapema. Nyumba zitauzwa kwa gharama ya ujenzi pamoja na faida ndogo, bila riba na kwa muda mrefu, kwa bei hiyo. Hemcan itafanya kazi hii yenyewe. Nyumba itawekwa rehani; deni likiisha, mtu anamiliki nyumba.",
    "goal3Body2": "Mpangilio wa kipaumbele: kwanza, watu wasio na ajira ambao familia yao haina nyumba na wao pia hawana, na watu wenye kazi lakini hawana nyumba; kisha watu ambao familia yao ina nyumba lakini wao hawana.",
    "goal3Body3": "Ghorofa ya chini ya kila jengo itatengwa kwa watu wenye ulemavu wasio na nyumba. Watu wasio na ajira watahakikishiwa kazi yenye mshahara mnono katika makazi au kwenye jengo la maduka. Hakuna atakayehangaika na malipo. Walio kwenye ndoa na wapya waliooana watapewa nafuu kulingana na idadi ya watoto watakapopata watoto.",
    "goal3Note": "Maelezo zaidi yatashirikiwa wakati ukifika.",
    "goalsClosing": "Malengo yaliyosalia, kwa ustawi na heri ya watu wetu na nchi yetu, yatashirikiwa wakati ukifika. Orodha yetu na safari yetu ni ndefu. Mungu awe rafiki na msaidizi wetu…",
