    "devicesSoonTitle": "Hivi karibuni",
    "devicesSoonBody1": "Vipengele kama udhibiti wa kifaa kwa mbali, kushiriki skrini, au kushughulikia faili/barua pepe kwa niaba yako havipo katika Hemcan kwa sasa — tumebadilisha skrini ya zamani ya onyesho iliyoahidi haya kwa maelezo haya ya kweli badala yake. Aina hiyo ya udhibiti wa kifaa inahitaji miundombinu halisi ya usalama/ruhusa, na ni kazi kubwa tutakayoifikiria kando siku za usoni.",
    "devicesSoonBody2": "Kile ambacho Hemcan inafanya kwa kweli sasa hivi: mazungumzo halisi ya AI, utaratibu wako wa arifa za kila siku, na kukumbuka historia yako ya mazungumzo — yote kwenye kifaa hiki. Kwa kuwa bado hakuna mfumo wa akaunti, mipangilio na mazungumzo yako ni mahususi kwa kifaa/kivinjari hiki — utahitaji kuvipanga tena kwenye kifaa chako kijacho.",
