    "goal1Title": "W każdym mieście co najmniej 2 pracowników Hemcan z pojazdami z logo HEMCAN zakupionymi od Togg",
    "goal1Body": "Ich zadania: utrzymywanie kontaktu z muchtarami (zwierzchnikami dzielnic) i wsiami w każdym powiecie oraz odnajdywanie osób w potrzebie dzięki śledzeniu wiadomości i mediów społecznościowych. Następnie zaspokajanie i monitorowanie ich potrzeb — jednorazowo lub miesięcznie, np. zdrowie, czynsz, karty żywnościowe i inne — zależnie od sytuacji.",
