    "goalsScope": "Priorytet: mój kraj, Turcja, a potem wszystkie kraje.",
    "goal2Title": "Bezlekowa terapia Neurofeedback dla osób, które chcą wyjść z uzależnienia",
    "goal2Body": "Dla osób uzależnionych od alkoholu i narkotyków — w pierwszej kolejności młodych — które naprawdę chcą się uwolnić od nałogu: zapewnienie im terapii Neurofeedback u dr. Tanju Sürmeli, metody bez leków, o której wysokiej skuteczności jesteśmy przekonani.",
    "goal2Note": "Ponieważ jest to bardzo kosztowna terapia, osoby muszą naprawdę chcieć rzucić nałóg. Uczestnicy będą wybierani bardzo starannie.",
    "goal3Title": "W każdym mieście duże osiedle z centrum handlowym: mieszkania bez odsetek, bez wpłaty wstępnej, na bardzo długi okres",
    "goal3Body1": "W każdym mieście powstanie co najmniej 1 duże osiedle z centrum handlowym obok. Mieszkania będą oferowane na bardzo długi okres i bez odsetek — nie będzie potrzebny bank partycypacyjny (islamski) ani zwykły bank, a nie zostanie pobrana żadna wpłata wstępna ani opłata partycypacyjna. Mieszkania będą sprzedawane po koszcie budowy powiększonym o niewielką marżę, bez odsetek i na długi okres, w tej cenie. Hemcan zajmie się tym sama. Mieszkanie zostanie obciążone hipoteką; po spłacie długu osoba staje się właścicielem.",
    "goal3Body2": "Kolejność priorytetów: najpierw osoby bezrobotne, które nie mają mieszkania w rodzinie ani na własne nazwisko, oraz osoby pracujące, ale bez mieszkania; następnie osoby, których rodzina ma mieszkanie, ale one same nie.",
    "goal3Body3": "Na parterze każdego bloku zostaną zarezerwowane mieszkania dla osób z niepełnosprawnościami, które nie mają mieszkania. Osobom bezrobotnym zostanie zagwarantowana dobrze płatna praca na osiedlu lub w centrum handlowym. Nikt nie będzie miał problemów z płatnościami. Małżeństwa i nowożeńcy otrzymają ułatwienia zależne od liczby dzieci, gdy je będą mieli.",
    "goal3Note": "Więcej szczegółów zostanie przedstawionych we właściwym czasie.",
    "goalsClosing": "Pozostałe cele, służące dobru i pomyślności naszego narodu i ojczyzny, zostaną przedstawione we właściwym czasie. Nasza lista i nasza droga są długie. Niech Bóg będzie naszym przyjacielem i pomocnikiem…",
