    "brandMeaningTitle": "Co oznacza \"Hemcan\"?",
    "brandMeaningBody": "Hemcan łączy dwa tureckie słowa: \"hem\" (razem, u twojego boku) i \"can\" (bliska osoba, bliski przyjaciel, dosłownie \"dusza\"). Opisuje kogoś, kto zawsze jest przy tobie, jak prawdziwy przyjaciel duszy — nasza nazwa niesie w sobie ducha jedności, wspólnoty i szczerej przyjaźni.",
