    "memorySubtitle": "Prawdziwa historia twoich rozmów z Hemcan",
    "memoryWhatBody": "Ten ekran to prawdziwa historia twoich rozmów z zakładki Asystent — a nie zmyślona lista „poznanych faktów”. Jest powiązana tylko z tożsamością tego urządzenia; możesz ją całkowicie usunąć w każdej chwili poniżej.",
    "memoryHistoryTitle": "Twoja historia rozmów",
    "memoryClearBtn": "Wyczyść historię",
    "memoryEmptyBody": "Nie masz jeszcze żadnej rozmowy. Zapytaj o coś Hemcan w zakładce Asystent, a twoja historia pojawi się tutaj.",
    "memoryHowTitle": "Jak Hemcan to wykorzystuje?",
    "memoryHowBody": "Hemcan korzysta z tej historii, żeby pamiętać twoją ostatnią rozmowę w trakcie czatu (mniej więcej ostatnie 20 wymienionych wiadomości). Jeśli wyczyścisz dane urządzenia/przeglądarki albo klikniesz „Wyczyść historię”, ten kontekst zniknie całkowicie — nie tworzymy trwałego profilu ani „zmyślonych wniosków” na twój temat, po prostu przechowujemy samą rozmowę.",
    "memoryCountLabel": "{n} wiadomości",
