    "devicesKicker": "Centrum dowodzenia",
    "devicesTitle": "Urządzenia",
    "devicesSubtitle": "Prawdziwa synchronizacja i sterowanie między urządzeniami nie są jeszcze częścią Hemcan.",
    "devicesSoonTitle": "Wkrótce",
    "devicesSoonBody1": "Funkcje takie jak zdalne sterowanie urządzeniem, udostępnianie ekranu czy obsługa plików/e-maili w twoim imieniu nie istnieją jeszcze w Hemcan — zamiast starego ekranu demo, który to obiecywał, umieściliśmy tę szczerą notatkę. Tego typu sterowanie urządzeniem wymaga prawdziwej infrastruktury bezpieczeństwa i uprawnień — to duże przedsięwzięcie, którym zajmiemy się osobno w przyszłości.",
    "devicesSoonBody2": "To, co Hemcan naprawdę robi teraz: prawdziwa rozmowa z AI, twoja codzienna rutyna powiadomień i zapamiętywanie historii rozmów — wszystko na tym urządzeniu. Ponieważ nie ma jeszcze systemu kont, twoje ustawienia i rozmowy są przypisane tylko do tego urządzenia/przeglądarki — na kolejnym urządzeniu trzeba je będzie skonfigurować od nowa.",
