    "planPill": "Hemcan Plan · Slechts {price} per maand",
    "orbReady": "Klaar",
    "orbSub": "Luistert · context actueel",
    "commandTitle": "Geef een opdracht",
    "commandSub": "Hemcan begrijpt wat te doen en laat je zijn grenzen zien.",
    "commandPlaceholder": "Bijvoorbeeld: Bereid me voor op de vergadering van morgen...",
    "tabAssistant": "Assistent",
    "tabAutomations": "Automatiseringen",
    "tabMemory": "Geheugen",
    "tabDevices": "Apparaten",
    "tabGoals": "Doelen",
    "goalsPriorityNote": "Onze doelen staan op volgorde van prioriteit.",
    "goal1Title": "In elke stad minstens 2 Hemcan-medewerkers met voertuigen met het HEMCAN-logo, gekocht bij Togg",
    "goal1Body": "Hun taak: contact houden met de muhtars (wijkhoofden) en dorpen van elk district en mensen in nood vinden via het nieuws en sociale media. Daarna hun behoeften vervullen en opvolgen — eenmalig of maandelijks, zoals gezondheid, huur, voedselkaarten en meer — afhankelijk van hun situatie.",
    "goal1Orphans": "Daarnaast: proberen er te zijn voor de wezen in elke stad, materieel en emotioneel.",
    "goalsScope": "Prioriteit: mijn eigen land, Turkije, en daarna alle landen.",
    "goal2Title": "Medicijnvrije Neurofeedback-behandeling voor mensen die van hun verslaving af willen",
    "goal2Body": "Voor mensen die verslaafd zijn aan alcohol en drugs — jongeren eerst — en echt van hun verslaving af willen: hen de Neurofeedback-behandeling laten volgen bij dr. Tanju Sürmeli, een medicijnvrije methode waarvan wij geloven dat die een hoog succespercentage heeft.",
    "goal2Note": "Omdat het een zeer dure behandeling is, moeten mensen echt willen stoppen. Deelnemers worden zorgvuldig geselecteerd.",
    "goal3Title": "In elke stad een groot woonpark met winkelcentrum: renteloze woningen, zonder aanbetaling, op zeer lange termijn",
    "goal3Body1": "In elke stad komt minstens 1 groot woonpark met een winkelcentrum ernaast. Woningen worden op zeer lange termijn en zonder rente verstrekt — er is geen participatiebank (islamitische bank) of gewone bank nodig en er wordt vooraf geen aanbetaling of participatiebijdrage gevraagd. Woningen worden verkocht tegen de bouwkosten plus een kleine winstmarge, renteloos en op lange termijn, tegen die prijs. Hemcan voert dit zelf uit. Op de woning komt een hypotheek; als de schuld is afgelost, wordt de persoon eigenaar.",
    "goal3Body2": "Volgorde van prioriteit: eerst werklozen die geen woning hebben in hun gezin en ook niet op eigen naam, en mensen die werk hebben maar geen woning; daarna mensen van wie het gezin wel een woning heeft maar zijzelf niet.",
    "goal3Body3": "Op de begane grond van elk blok worden appartementen gereserveerd voor mensen met een beperking die geen woning hebben. Werklozen krijgen een goedbetaalde baan gegarandeerd in het woonpark of het winkelcentrum. Niemand krijgt problemen met de betalingen. Gehuwden en pasgetrouwden krijgen tegemoetkomingen naar het aantal kinderen zodra ze kinderen hebben.",
    "goal3Note": "Meer details worden gedeeld wanneer de tijd daar is.",
    "goalsClosing": "De overige doelen, ten bate van het welzijn en het goede van ons volk en vaderland, worden gedeeld wanneer de tijd daar is. Onze lijst en onze weg zijn lang. Moge God onze vriend en helper zijn…",
    "planTitle": "Hemcan Plan",
    "planHeadline": "Slechts {price} per maand",
