    "devicesSoonBody1": "Functies zoals externe apparaatbesturing, schermdeling of het namens jou afhandelen van bestanden/e-mails bestaan momenteel niet in Hemcan — we hebben een oud demoscherm dat dit beloofde vervangen door deze eerlijke melding. Dat soort apparaatbesturing vereist echte beveiligings- en rechteninfrastructuur en is een groot project dat we later apart bekijken.",
